-- Generated source references; not native quest records.
local addon = WordHunterWoW_Addon
local compat = addon and addon.Compat
local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[24961] = { id = 24961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Truth of the Grave", description = "Earlier on, I saw a young Forsaken woman running towards the old inn.  She was screaming for her life, pleading to be taken back home.\n\nNot all of us are as resolute as others, {name}.  Even so, we must accept our fate as undead if we are to rise up against those that would put us down.\n\nTake my hand mirror and show it to the young woman.  She needs to see what she really is, and join us in our cause.  Besides... we can use all the bodies that we can get.", progress = "Have you spoken with her yet?  She needs to be shown the truth.", completion = "You say she ran away?  What a shame.\n\nVery well.  As long as she's maintained her free will, there's still hope.", objectives = "Find Lilian Voss inside the large inn in Deathknell. Then speak with her to show her Elreth's Hand Mirror.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24962] = { id = 24962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trail-Worn Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the hunter trainer Xavier. I would take some time to read it before heading out again.", progress = "Ah, so you've arrived. Good. I overheard that a few others were able to escape \"death\" and were heading into town. Perhaps that resilience will pay off in the future also.\n\nYou may thank Sylvanas for your freedom... freedom of mind and body. Though you still remain tortured by the plague and its effects, you are now free to come and go as you see fit.", completion = "I will be here to train you as you grow in experience... find me as often as you like. I charge a minimal fee, but you'll find everything I can teach you to be worthwhile.\n\nGo now and test your skill. Many more things will become known to you as you gain experience, some of which I am unable to discuss with you here. Just know that Sylvanas will need hunters with your type of cunning in the future.\n\nYou will be the backbone of our salvation. Do not forget it.", objectives = "Read the Trail-Worn Scroll and speak to Xavier the Huntsman in Deathknell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24963] = { id = 24963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maul 'Em With Kindness", description = "Okay, babe, listen up. There's two ways to get people to do what you want. You can provide goods, services, and things people want...or you can beat the living daylights out of them.\n\nI've often found it's useful to do both at the same time, and you're pretty familiar with both methods by now. Take these little silithid treats, go and beat some ogres dizzy, and then give them the treat before you knock them completely dead, 'kay?", progress = "Keep at it, babe. I can see 'em from here, don't get lazy on me.", completion = "Good job, you've taught half the ogres here to fear and respect anything vaguely {race}-shaped.\n\nIt's amazing what a little reward will do to keep people under your thumb, isn't it? Here's your payment, by the way.\n\n...what's with that look?", objectives = "Use the Bilgewater Cartel Promotional Delicacy Morsels on 8 Dunemaul Ogres after weakening them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24964] = { id = 24964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thrill of the Hunt", description = "I've been told that I'm supposed to train you how to be a hunter.  That's all well and good, but in my opinion, you'll get more training out in the field than you will talking about theories with me.\n\nGo out, get some more experience, and see if you learn any new tricks. Then you can come back and show me.", completion = "You seem to be somewhat of a natural, {name}.  This is good.  I can't teach you everything myself.\n\nGo, practice what we've discussed today.  Return when you're stronger, and we'll cover some more tricks and abilities.", objectives = "Reach level 3 to learn Steady Shot, then practice using Steady Shot 5 times on a Training Dummy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24965] = { id = 24965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magic Training", description = "Let's get some work done, shall we?\n\nAs you grow in power, your connection to the arcane will deepen, granting you access to new spells.\n\nYou'll see. Go, get some more experience, then come back and demonstrate what you've learned.", completion = "I've got to admit, the spell I just taught you probably won't increase your intellect severalfold.  That was a lie to get you to buy my services.  But it will still be a helpful spell for you and your allies.\n\nNo hard feelings!", objectives = "Reach Level 3 to learn Frost Nova, then practice using it 2 times against a Training Dummy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24966] = { id = 24966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Light and Shadows", description = "A Forsaken priest is a curious beast,\n<his/her> path an unusual course.\n$G His: Her; shadowy rites cannot come from the Light, so <he/she> seeks a more sinister source.\n\nNot only has the world forsaken us, {name}... it seems the Light has left us as well.  As the poem hints, however... we are not without power.\n\nGo, get more experience, grow your power. Return to me, and demonstrate what you have learned.", completion = "You're a good student, {name}.  You'll go far.  If you ever need any further training, return to me and I'll happily oblige.", objectives = "Reach level 3 to learn Shadow Word: Pain. Then, practice casting it 5 times on training dummies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24967] = { id = 24967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stab!", description = "Quiet down!  I don't want these novices around us to hear what we're about to discuss.\n\nListen up... {name}, is it? Soon, you'll learn something that'll change the way you operate as a rogue.  You'll be able to follow up on your attacks with a deadly finishing move. Maybe even slide a dagger between their vertebrae.\n\nTo learn it, you just gotta get some more experience. Don't worry, you'll figure it out.", completion = "Trust me, this'll be worth the money.  And hey - if you need any more training, stop by any time.", objectives = "Reach level 3 to learn Eviscerate, then practice using Eviscerate 3 times on a Training Dummy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24968] = { id = 24968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Deeds", description = "As you continue your career as a warlock, you'll begin to hear the voices of fel power... they will reveal their secrets, teaching you new spells.\n\nI want to see you learn a new spell and try it out on one of the dummies here.", completion = "Congratulations... you're one step closer to being a master of the dark arts.  Go practice a bit, and return when you're stronger.  I'll have more to teach you then.", objectives = "Reach level 3 to learn Corruption, then practice casting Corruption 5 times on a Training Dummy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24969] = { id = 24969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charging into Battle", description = "If you want to become a stronger warrior, you'll need to work on your weapons.  You'll find stronger swords and larger shields out on your adventures, that I have no doubt about.\n\nBut it isn't just your physical armory that will get stronger - you'll also begin to discover new techniques. Go, get some experience, learn something new, then come back and show me.", completion = "You have the makings of a great {class}, {name}.  Go, practice what we've discussed, and return when you are stronger.  Then I may have more to teach you.", objectives = "Reach level 3 to learn Charge, then practice using Charge on a Training Dummy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24970] = { id = 24970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Better Than the Zombies", description = "While you were inside that cave, your big friend Darnell came by with some alarming news.\n\nSince the val'kyr arrived, we've seen more and more undead that chose not to join our forces under the banner of the Dark Lady.  They've been gathering at a small camp here in the valley, and now they've organized forces.\n\nThey plan to attack Deathknell, {class}.\n\nDarnell is just down the road, to the east.  Be careful, {name}.  While those undead aren't completely brainless, they're still not quite right in the head.", completion = "{name}.  You made it.\n\nYou see those tents up there?  That's where we're headed.  The battle's probably already started.", objectives = "Report to Darnell at Deathknell in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24971] = { id = 24971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Rotbrain Encampment", description = "While you were taking care of matters for Executor Arren, I went off on an assignment of my own.  Shadow Priest Sarvis asked me to peek in on the Rotbrain camp.\n\nThere's a reason why they're called Rotbrains.\n\nTheir leader goes by the name of Marshal Redpath, and he's an absolute beast.\n\nLook, {name}... the attack is starting.  You're better in combat than I am.  Get in there and help out!\n\nWhen you're done, meet up with Shadow Priest Sarvis in the chapel.  Good luck, {name}.", completion = "Being born again under the power of a val'kyr is a strenuous process.  Many don't survive the shock, turning into zombies or ghouls.\n\nOthers retain just enough humanity to seem normal on the outside... but they're sick inside.  We should have slain those rotbrains the day they were raised.\n\nAs for you... you're a strong {class}, {name}.  I knew you'd do well.  You'll be headed out of Deathknell soon.", objectives = "Kill Marshal Redpath and 8 Rotbrain undead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24972] = { id = 24972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vital Intelligence", description = "<Sarvis produces a piece of paper from within his robes.>\n\nThese will need to be taken to my field agent, Deathguard Simmer.  This information contains the whereabouts of the last few holdouts from the Scarlet Crusade.  We will destroy these crusaders, once and for all.  And I have a feeling you'll be instrumental in that effort, {name}.\n\nTake the road north out of Deathknell.  Soon after entering Tirisfal proper, you'll see a large manse.  Simmer's inside.", progress = "Yes, what do you want?", completion = "Yes, this is very good. You've done well in obtaining this information, {name}. Hmm... names of the Scarlet Crusade officers in the Tirisfal Glades...\n\nImagine the blow we could deal to the morale of those bloody zealots if we were to kill their leaders in one swift strike.  I will pass this information forward.", objectives = "Deliver the Scarlet Crusade Documents to Deathguard Simmer at Calston Estate in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24973] = { id = 24973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Night Web's Hollow", description = "One of our greatest struggles is obtaining the natural resources we need to survive.  Gold was scarce in Lordaeron, even in the height of the Alliance's power so many years ago.\n\nThere is a gold mine to the west that has been overrun with spiders.  We need gold from the mine, but we can't very well get it while the spiders are crawling around in there.  I've not much manpower to commit to the task, so we'll just have to do it little by little.\n\nGet up there and see what you can do for us, {name}.", progress = "Be wary of the spiders' venom, {name}. If you feel a sharp burning, you may want to have it looked at.", completion = "Well, it's a start.  It'll take a few weeks or months to fully clean out the infestation.  After that, we'll have to get down there with some torches to burn away the webbing.\n\nYou've done your duty well, {name}.", objectives = "Kill 8 Young Night Web Spiders and 5 Night Web Spiders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24974] = { id = 24974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ever So Lonely", description = "You work hard your whole life, and what do you get?  Killed by a plague.  Then you work even harder in undeath, and what do you get?  Money, yes, and a small estate with a few pesky hangers-on, but happiness?  Not so much.\n\nI'm lonely in my old age, {name}.  I need a companion.  Use this leash on one of the murlocs at the Whispering Shore to the northwest.  You'll have to weaken it first before it can be leashed.  Then bring it back to me.", progress = "Oh, the pain of loneliness is too much to bear!", completion = "Oh, look at him!  Isn't he the most adorable thing you've ever seen?  Thank you, {name}.  I feel more energetic already.", objectives = "Use the Murloc Leash on a Vile Fin murloc at the Whispering Shore, then return it to Sedrick Calston at Calston Estate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24975] = { id = 24975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fields of Grief", description = "What have we here?  You look like a fledgling {class}.  If you hope to prove yourself to the Dark Lady, you need to learn the ways of the Forsaken.\n\nTo the west you'll find a farm.  Humans infest the land like mold on a rotting corpse.  And worse yet, the Scarlet Crusade patrols nearby from their tower.  Teach those scum a lesson and steal 10 of their precious pumpkins.\n\nOnce you have 10, bring them back to me.", progress = "Were you able to gather 10 pumpkins yet, {name}?", completion = "You have performed your bidding well, young {class}.  You are proving yourself to be quite an asset to the Dark Lady's army.", objectives = "Steal 10 pumpkins from the Solliden Farmstead in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24976] = { id = 24976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Variety is the Spice of Death", description = "These pumpkins have a purpose, {class}.  They'll be the delivery mechanism for my latest batch of plague, which should be a particularly painful and virulent concoction.  However, the plague requires a few rare ingredients.\n\nWe'll need Marrowpetals, which grow at the bottom of Stillwater Pond, just to the east of here.  We'll also need Xavren's thorn, which grows on rocky cliffs to the northwest.  Finally, we need some briny sea cucumbers, found in the surf off of Whispering Shore.", progress = "I've got a feeling this will be my best batch yet, good {class}.", completion = "Excellent work, {name}.  Now comes the fun part.", objectives = "Obtain 4 Marrowpetals, 4 Xavren's Thorns, and 8 Briny Sea Cucumbers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24977] = { id = 24977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Johaan's Experiment", description = "Harmless pumpkins, right?  Or so it would seem.  If we are to defeat the Scourge advances from the North and the human infestation from the South we need to start realizing the full potential of our gift of undeath.\n\nWith a little ingenuity a simple pumpkin becomes an agent for our Dark Lady.  This pumpkin, laced with my latest formula, will prove to be quite a treat.\n\nYet another Scarlet Zealot has been captured and is being kept outside, by the gazebo.  Take this pumpkin to the fool.", progress = "Stay away, foul and unholy creature!  May the Light protect me!  The Scarlet Crusade shall rid Azeroth of your...\n\n...oh wait.  Is that food for me?  I am so hungry...", completion = "By the Light!  Finally some food!  Sweet, sweet pumpkin....", objectives = "Take the Laced Pumpkin to the Captured Scarlet Zealot at the gazebo at Calston Estate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24978] = { id = 24978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reaping the Reapers", description = "Humans are notoriously fickle creatures.  The farmers to the west are no exception.  Sure, they may be plowing their fields peacefully now, but tomorrow, they may be raising their scythes against us.  The Alliance looms close by in Gilneas, and the power of Stormwind looms to the south... any of these could recruit these tillers and use them as a wedge against us.\n\nI want them dead.  See to it that it's done.", completion = "You've the makings of a mighty {class}, {race}.  I heard the cries of those humans from all the way over here.  Perhaps soon we will be rid of this human blight.", objectives = "Kill 10 Tirisfal Farmers or Tirisfal Farmhands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24979] = { id = 24979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scarlet Letter", description = "Lieutenant Gebler:\n\nHow curious that you would decide to take a prisoner... an undead one at that.  What were you thinking?  Do you think that, just because of the prisoner's former status, that she would be above the edicts of the Scarlet Crusade?\n\nThis is most troubling, Gebler.  I would remind you that there are penalties for such behavior.  I command you to execute the prisoner at once.  She is no longer one of us.", progress = "A letter?  What does it say?", completion = "The Scarlet Crusade takes no prisoners.  That they would do so with this young woman... curious.\n\nThe powers that you describe are even curiouser.  She passed through the bars of her prison and killed her captor?  Why hadn't she done that in the first place?", objectives = "Find the prisoner in Scarlet Palisade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24980] = { id = 24980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Palisade", description = "We need someone with \"initiative\" like yourself to drive the Scarlet Crusade to the grave.\n\nProve to me you are capable of serving The Dark Lady by travelling west to the tower past the Solliden Farmstead and slaying 10 warriors of the Scarlet Crusade.", completion = "Most excellent, {class}.  Your skill in the art of combat is undeniable.", objectives = "Kill 10 Scarlet Warriors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24981] = { id = 24981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thorn in our Side", description = "Information we've received from Executor Arren in Deathknell contain all the details we need to wipe the human infestation from the lands.  According to the information, The Scarlet Crusade has assigned Captain Perrine and a brigade to the ruined tower southwest of Brill.\n\nKill 3 of his zealots and 3 of his missionaries.  And while you're there, see if you can dig up any other information about what they're up to.", progress = "We shall herd the Scarlet Crusade like cattle to their demise.", completion = "It sounds like we'll have to keep our eyes out for this Voss character.  I don't expect any Forsaken to receive a reward if we capture her... I'm just worried she'll eventually turn against us.", objectives = "Kill 3 Scarlet Zealots and 3 Scarlet Missionaries, and obtain the Scarlet Epistle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24982] = { id = 24982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Forsaken", description = "Speaking frankly, the Forsaken of yesteryear were a sniveling, pathetic group.  We huddled together in decrepit old human buildings, hiding from the Scourge, cowering from the Alliance, and groveling at the foot of the Horde.\n\nLook before you now, and see the product of the new Forsaken.  We have made our mark here on Azeroth, and that mark will grow.  Our dominion will soon blanket the world!\n\nYou want my advice?  Speak with Magistrate Sevren in Brill, down this road.  He runs that town.", completion = "Yes, I'm Brill's local magistrate, reporting directly to the Dark Lady.  Impress me, and you may end up meeting the Banshee Queen herself.  Now, onto your first task...", objectives = "Report to Magistrate Sevren at Brill in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24983] = { id = 24983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forsaken Duties", description = "I need a fresh report from our Deathguard waystation to the east.\n\nI must know if more Scourge forces have slipped past The Bulwark and into Tirisfal.  Our vigilance on the border to the Plaguelands must be maintained - we can't let the Scourge get a stronger foothold here!\n\nTravel south along the road, then east at the fork to the waystation.  Speak with Deathguard Linnea.  She has the information I need.", completion = "Magistrate Sevren wants a report?  Very well: the defenders at The Bulwark are holding the majority of the Scourge at bay, but some do slip through on occasion.\n\nWe have seen sporadic Scourge activity east of this station, with a concentration around the Balnir Farmstead.", objectives = "Speak with Deathguard Linnea at Death's Watch Waystation in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24984] = { id = 24984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prodigal Lich", description = "Long ago, the mage Gunther Arcanus, along with Bethor Iceshard and the now-Scourge Necromancer Thule Ravenclaw, were friends and students within the Kirin Tor - a society of mages in Dalaran.\n\nGunther fell to the Plague, but we thought he either remained dead, or was raised into the ranks of the Lich King.  We now know he is free.\n\nWe must have him.  If you travel east, you will find him on an island in Brightwater Lake.  Convince him to join our ranks.", objectives = "Report to Gunther Arcanus at Gunther's Retreat in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24985] = { id = 24985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Allegiance", description = "Fine.  I will continue with this charade, but only because I sense in you a spark of... excellence.  But before I believe you I must have proof that you are enemy to the Scourge.\n\nThere is an old, bloody altar just off the southern coast of this island.  It is used by a powerful Scourge agent, Lillith Nefara.\n\nTake a Candle of Beckoning from this crate here.  Light it on the altar and Lillith will awake.  Destroy Lillith, and I will believe you are an ally.", objectives = "Obtain a Candle of Beckoning.\n\nSummon Lillith Nefara and kill her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24986] = { id = 24986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prodigal Lich Returns", description = "Take this Nether Gem to my old comrade Bethor, who resides in the Undercity.  It will let us communicate ... and I have much to tell him.", objectives = "Bring the Nether Gem to Bethor Iceshard in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24987] = { id = 24987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Lady, Watch Over Us", description = "In fact, why don't you speak with Lady Sylvanas herself?  The presence of another Kirin Tor-trained mage among our ranks is an occasion worthy of an audience.", sourceObjective = "Speak with Lady Sylvanas Windrunner in the Undercity.", sourceObjectiveStatus = "unverified-source-field" }
quests[24988] = { id = 24988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chill of Death", description = "It's so cold, now.  The Plague of Undeath crawls through my veins like an icy serpent.  The mindless state will be upon me soon.  But no doomed destiny will prevent me from serving our Dark Lady.  When the call arose I sewed body bags for the fallen soldiers of Sylvanas's mighty army.\n\nNow my hands shake from the chill.  If you would bring me five duskbat pelts, I could sew myself a blanket.  Help me, {name}, so that I can continue to serve the cause.", progress = "Do you have five duskbat pelts yet, {name}?", completion = "I appreciate your efforts, {name}.  May Sylvanas recognize your bravery one day. . . .", objectives = "Obtain five Duskbat Pelts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24989] = { id = 24989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Magistrate", description = "You should return to Magistrate Sevren with the information I gave you.  He'll want it as soon as possible, so be swift.", completion = "It is troubling to hear of the Scourge slipping past the Bulwark.  Even now, they are ceaseless in their assaults.\n\nBut we will not give in.  The Lich King is dead; we will not be taken again!", objectives = "Return to Magistrate Sevren in Brill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24990] = { id = 24990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkhound Pounding", description = "Lady Sylvanas has called upon the Royal Apothecary Society.  She has challenged us to concoct a new plague, a plague deadlier than any ailment on Azeroth. This new disease will bring our enemies - living and dead - to ruin.\n\nMy studies show that the blood of beasts might prove to be the key. Here, fill these vials with darkhound blood so I can test my theory.", progress = "Have you collected the darkhound blood yet, {name}? Time is fleeting!", completion = "You have done well, {name} and I thank you for your efforts.", objectives = "Collect 5 Vials of Darkhound Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24991] = { id = 24991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garren's Haunt", description = "As you're probably already realizing, the Royal Apothecary Society is a widespread organization.  We take our plague-alchemy seriously.  It is our belief that the more agents we have performing experiments, the sooner we will realize our objective.\n\nOne of our agents performs his work at a small encampment to the north of here.  His name is Jerrod, and he could use an apprentice of your... stature.", completion = "Holland?  He's an amateur.  You don't need a fancy two-story apothecarium to make plague... you need love.  And maybe some good assistants.\n\nLet me show you how plague is REALLY made.", objectives = "Report to Apothecary Jerrod at Garren's Haunt in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24992] = { id = 24992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escaped From Gilneas", description = "As far as you know, a worgen rogue roaming in Tirisfal is a new development.  This is something that Executor Zygand would certainly be interested in.", completion = "Hmm... yes, that makes sense.  Since the worgen have come streaming out of Gilneas, I knew it would only be a matter of time before they arrived here in Tirisfal.", objectives = "Report the worgen's presence to Executor Zygand at Brill in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24993] = { id = 24993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Annihilate the Worgen", description = "These worgen must be dealt with, and quickly.  Our first priority is to eliminate any which may have infiltrated Brill.\n\nI want you to be on the lookout for any suspicious activity here in Brill, {name}.  We know that these worgen can hide in the shadows, so look for any signs you can find... footsteps, kicked-up rocks... anything.", completion = "To think, they've been right under our noses!  I'll put my deathguards on alert... this will NOT happen again.", objectives = "Find and kill 5 Worgen Infiltrators within Brill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24994] = { id = 24994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doom Weed", description = "My envoy just delivered me a bushel of gloom weed.  Gloom weed!  I don't need gloom weed, I need doom weed!  You can see the predicament that I'm in, {name}.\n\nI'll make it worth your while to gather what I need. Bring back to me enough doom weed and I'll give you a suitable reward.\n\nIt is my understanding that they like to plague the flora near the mass gravesite, to the north of the Brill graveyard. Hurry and be mindful of the gnolls in the area.", progress = "<The apothecary mutters to himself.>\n\nThey brought me gloom weed?  GLOOM WEED?!", completion = "Ah, my doom weed. Excellent!\n\n<Apothecary Jerrod rubs his hands together greedily.>\n\nThese will come in quite handy. You've done me, uh, the Lady, a fine service today, {name}. As promised, here is the reward that you deserve.", objectives = "Collect 10 Doom Weed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24995] = { id = 24995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off the Scales", description = "While you were collecting samples for me, my experiments led me to realize that more reagents will be required for this new disease to spread properly.  Poisoning some hapless victim is child's play.  Plaguing an entire world proves to be a bit more complicated.\n\nI will need several scales from murlocs in the vicinity.  You will find the creatures ambling brainlessly along the coast to the north.", progress = "{name}, were you able to obtain those scales from the murlocs?", completion = "The scales are perfect, {name}. Exactly what I needed for this concoction.", objectives = "Obtain 5 Vile Fin Scales.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24996] = { id = 24996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holland's Experiment", description = "I am to understand that another one of those foolish Dwarven Mountaineers has just been captured.  The deathguard has him stored here in this building, and they've assigned one of their own to persuade him not to escape.\n\nWhy don't you go see how the Captured Mountaineer enjoys this special drink I made for him?  It contains a subtle hint of what The Dark Lady has planned for the rest of Azeroth.", progress = "Why if I had my trusted rifle you'd be as good as dead, {class}.  Just wait until the Steam Tank Brigade arrives to rescue me!", completion = "Ah, a drink at last.  What matter of ale is this?  I'm sure it's no Rhapsody Malt but I'll take anything to wet the old whistle at this point.", objectives = "Bring Holland's Special Drink to the Captured Mountaineer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24997] = { id = 24997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Graverobbers", description = "The mass graves within the forest to the west of us were made to accommodate the... impressive... number of deaths Tirisfal suffered when the plague first came.  \n\nThe bodies in these graves have so far been spared an undeath, but the Scourge now send Rot Hide gnolls to gather the corpses and use them to bolster their armies.  This cannot be allowed!\n\nYour task is twofold: slay the Rot Hides at the mass grave and Garren's Haunt, and gather from them the embalming ichor that gives them life.", progress = "Is your task complete?  Have you destroyed those dog-things and drained them of their ichor?", completion = "Expertly done, {name}.  The Scourge are mistaken if they think they can use those corpses against us, and the fluid you gathered from the Rot Hide slaves will be studied by my master.  It may have secrets we can use against them.", objectives = "Kill Rot Hide Graverobbers and Rot Hide Mongrels, and obtain 6 flasks of Embalming Ichor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24998] = { id = 24998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maggot Eye", description = "Maggot Eye is a foul beast, even by gnoll standards.  He leads a band of renegade gnolls through the land, tearing up the glades and stealing whatever corpses he can find along the way.\n\nThose are our corpses!  We had plans for those!\n\nMaggot Eye resides just up the path from us.  Show him no mercy.  Mercy is for the weak.", progress = "Yes?", completion = "Excellent work!  Now if only I can convince Jerrod to let us move our operation into that shack...", objectives = "Kill Maggot Eye and obtain his paw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[24999] = { id = 24999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Planting the Seed of Fear", description = "It seems that Jerrod has you hunting the murlocs to the north.  That's good... we can use their parts for our poisons.  I get a little worried sometimes, though...\n\nThe Vile Fin spawning grounds are not far off Tirisfal's northern coast, so you'll probably notice several tadpoles among the adults on the shore.  If these impressionable young murlocs were to seek revenge against us... that could ruin us.  Go chase them, and show them that the Forsaken and the Horde are not to be trifled with.", completion = "Did they run from you, {name}?  Good.  This is better than killing them... if they live to tell the tale, then future generations of murlocs will learn to fear us.", objectives = "Chase 12 Vile Fin Tadpoles until they pass out in fear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25000] = { id = 25000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teegan's People", description = "Hey, {class}!\n\nAre you headed to support Corporal Teegan? He's in charge of keeping the supply routes open.\n\nHe's got two of the most ornery dwarves I've ever met in charge of sundries. If you want to make an impression on those two crotchety hunters, you're going to need to show that you can hold your own against the predators around here.\n\nThe raptors west of the hold here are especially vicious. Bring Goucho some fresh hides and you'll make an impression while supplying the troops in one swoop.", progress = "What is it, {class}? This here camp ain't fit for sight-seein'.", completion = "Hey, you're tougher than you look. These terrortooth hides reflect arrows and turn axe-blades - they don't go down easy, but their hides are worth their weight in silver in these light-forsaken Barrens. Nice work.", objectives = "Kill Terrortooth Runners and Terrortooth Scytheclaws to collect 8 Terrortooth Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25001] = { id = 25001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandscraper", description = "My other assistants are making sure our proud new comrades are put into comfy cages and shipped to where they're needed most. For the Horde. Meanwhile, we've got one last item on our agenda.\n\nSandscraper, the chief of the Dunemaul Clan, is probably too dumb to even be aware of what we're doing here. But I absolutely loathe unfinished business, babe. He's lurking in the den just over there to the west. Knuckle down, take him out, and we'll be good to sign off on this, 'kay?", completion = "And that's a wrap! Nothing left here for us but sand. Good job, babe.\n\nWell, maybe I shouldn't be so hasty. Did you find anything in that ogre den?", objectives = "Kill Sandscraper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25002] = { id = 25002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scavenged", description = "<You discover a cargo manifest on the body, detailing a long list of sundries urgently needed on the front.>\n\n<A bloody trail in the dirt indicates bodies were dragged south of here, toward the raptor dens.>\n\n<The raptors may have dragged away the supplies, as well. Retrieving those supplies for Corporal Teegan could help salvage this disaster!>", progress = "What? My supply caravan was sacked by those cold-blooded scissor-paw things?", completion = "My supplies! Well, that showed some real initiative, {class}. Those rap-saws or whatever they're called have torn lesser men to ribbons. Thank you!", objectives = "Retrieve 10 Northwatch Supply Crates from the Raptor Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25003] = { id = 25003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Family Crypt", description = "The strongest point in the mills is the Agamand Family Crypt.  With necromancy, Captain Dargol has raised the ancestors of the Agamands and plans to use them against us.\n\nThis cannot pass, and you must stop it.  Travel to the Agamand Family Crypt and defeat the raised Agamand ancestors.", progress = "Time is not a luxury we have, {name}.  With each passing hour, the Scourge's hold on Tirisfal Glades grows more firm.", completion = "Your actions struck a telling blow against the Scourge.  And your victory will not go unnoticed - not by the Forsaken, nor by our enemies.\n\nContinue the struggle as we all do, {name}, and one day the Forsaken will have the dominion over Azeroth that they are owed!", objectives = "Kill 5 Wailing Ancestors and 5 Rotting Ancestors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25004] = { id = 25004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mills Overrun", description = "The Scourge are trying to form a base here at the Agamand Mills.  If they do, then they can stage further attacks within Tirisfal.\n\nThe orders have been given.  The Scourge in the Mills must be destroyed.\n\nCollect Notched Ribs from Rattlecage and Cracked Skull Soldiers, and Blackened Skulls from Darkeye Bonecasters.", progress = "Our battles with the Scourge wage on, {name}.  Do your part and throw those cursed, mindless {race} back into the Plaguelands!", completion = "Your efforts are appreciated, {name}.  I will not thank you for doing what is necessary, but I will remember your name.", objectives = "Gather 5 Notched Ribs and 3 Blackened Skulls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25005] = { id = 25005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Sevren", description = "I have destroyed the remains you've given me, {name}.  That is, all remains except for these...\n\nDevlin Agamand was weak and sharp-tongued in life, and was among the first to succumb to the plague.  He existed as a slave of the Scourge for a long time, longer than most.  As such, he may possess knowledge that would be of value to us.\n\nBring his remains to Magistrate Sevren, and tell him what I've told you.  He'll know what to do.", progress = "The fetor of Scourge hangs about you, {name}.  What is it you seek?", completion = "Devlin Agamand?  Is that him you carry in your sack there?  Ha!\n\nYes, I know what Coleman wants to try, and I want to try it too.  I hope you're prepared, {name}.", objectives = "Speak with Magistrate Sevren at Brill in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25006] = { id = 25006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grasp Weakens", description = "While the Frozen Throne lies dormant, the grasp that the Lich King once held over the Scourge grows ever-weaker.  His grip on a weakling like Devlin Agamand should be weak enough that we can remove it entirely.\n\nSpeak with Shadow Priestess Malia in the manor on the east side of town.  She will assist you in the procedure.", progress = "What did you find out?", completion = "Ah, how unfortunate.  Perhaps the Scourge's dominion over Devlin's mind remained too strong.  Or perhaps our methods are simply not strong enough.  It's also possible that Devlin was too simple-minded to comprehend what we were asking him.", objectives = "Speak with Shadow Priestess Malia in Brill and participate in the extraction of Devlin Agamand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25007] = { id = 25007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "East... Always to the East", description = "You've done much for us here, {name}, but <men/women> of your caliber are needed elsewhere.\n\nTo the east lies the Bulwark: a fortified barricade against the ravages of the Plaguelands.  The Bulwark protects us from Scourge invasions, and has allowed us enough sanctity to build up our forces here in Tirisfal Glades.\n\nGo, speak with High Executor Derrington.  He is an ally, and will doubtless appreciate whatever aid you can give him.", completion = "<The High Executor sizes you up.>\n\nNot much of a {class}, are you?  Well, you will be when I'm done with you.", objectives = "Report to High Executor Derrington at the Bulwark in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25008] = { id = 25008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filthy Animals", description = "You probably caught wind of some of them Hecklefang scavengers on the way in - they reek worse than ol' Durty Pete here. Worthless animals! They steal our kills, rummage through our supplies, and worse... they ain't good for eatin'.\n\nGo kill some.\n\nThen kill some more, if you want to.", completion = "Ooooo-oooh aye! The best Hecklefangs are the dead ones.", objectives = "Kill 6 Hecklefang Scavengers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25009] = { id = 25009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At War With The Scarlet Crusade", description = "Though the strength of the Scarlet Crusade wanes, we are still at war.  The report Executor Arren sent me indicates Scarlet Crusaders have been raiding from the ruined tower in southeastern Tirisfal near the Balnir Farmstead under the command of Captain Vachon.\n\nKill 3 of his zealots and 4 of his friars. It should prove to be a devastating blow to the Crusade!", completion = "Your actions will slow down the Scarlet Crusade's advancement in Tirisfal quite a bit... hopefully for good.  But other threats loom.", objectives = "Slay 3 Scarlet Zealots and 4 Scarlet Friars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25010] = { id = 25010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Deadly New Ally", description = "Shortly before you arrived at the Bulwark, I was approached by the most unusual young undead woman.  She swore enmity against the Scarlet Crusade, so I sent her to work on our enemies to the north.  You say you saw some dead crusaders earlier?  Those were probably her work.\n\nGo check up on her, and see if she can use any assistance in her vendetta against the Crusade... though I wouldn't be surprised if she's already killed them all.", completion = "As you look over the ruins of the camp, you hear a whisper behind you.\n\n<\"I could kill you right now if I wanted to.  You'd better watch your step, {race}.\">", objectives = "Look for your new ally at the Scarlet Encampment in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25011] = { id = 25011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Bigger and Better Things", description = "There isn't much more glory for you here on the Bulwark, {name}.  You've done enough already.  There may, however, be further adventures waiting in Silverpine Forest.\n\nSpeak with my bat man, Timothy Cunningham.  He'll give you a ride to Brill, free of charge.", completion = "Sure, I'll give you a ride.  If High Executor Derrington asks for it, then technically I have to.", objectives = "Speak with Timothy Cunningham at the Bulwark in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25012] = { id = 25012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take to the Skies", description = "If you're headed back to Brill, you'll want to stop by Executor Zygand on your way out.  I hear there's some excitement going on in Silverpine Forest, to the south.  He'll know more than I do.\n\nSpeak with me again when you're ready to head out.", completion = "Welcome back, {name}.  I've heard stories from the east.  Who would have thought that a young {race} {class} like you would have been the one to wipe out the last whimpering remnants of the Scarlet Crusade?", objectives = "Speak with Executor Zygand at Brill in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25013] = { id = 25013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Oomph", description = "<Dithers samples his latest concoction.>\n\nHmm... this isn't quite there.  It needs something to give it a little more zing.  I've got it!  The spiders to the north have a potent venom that'll do the trick.  See if you can extract some for me, {name}?", progress = "Do you have some venom from a Vicious Night Web Spider yet, {name}?  It's the final component I need in order to test my experiment.", completion = "Ah, this venom will do perfectly, {name}.  Everything else has been added to my concoction and boiled down.  Thank you, {class}!", objectives = "Obtain 4 samples of Vicious Night Web Spider Venom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25014] = { id = 25014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandscraper's Treasure", description = "Inside this weathered stone chest at the back of Stonescraper's lair, you find a curious artifact.\n\nShaped like a beetle, its surface is a smooth, brilliant blue, lined with gold. It looks mechanical, but unlike anything you've seen crafted by mortal hands, and very old.\n\nMegs will probably be interested in this.", progress = "Find something?", completion = "You found that in the ogre den? That's...\n\n...nothing to get excited about, I'm sure! I'm sure it's just...a perfectly benign trinket...that I'm going to give you precisely detailed instructions on exactly how to handle.\n\n<Megs drops her voice to a whisper.>\n\nKeep your voice down and don't wave that thing around.", objectives = "Talk to Megs Dreadshredder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25015] = { id = 25015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make 'em Squeal", description = "One of the native species in Kalimdor is the 'quilboar.' Prickly little buggers. Reason enough to hate this continent.\n\nThe raids started shortly after we established our forward camps. Worse, those spiny fiends seem to thrive in this thorny hell of a jungle. I need you to help beat them back so we can re-establish contact with Forward Command.\n\nWhile you're out there, acquire one of those twisted branches their casters seem to be using to manipulate the jungle growth...", progress = "I should mention, you're probably going to need a machete to hack through this mess.\n\nThis jungle came out of nowhere!", completion = "<Corporal Teegan nods as you deliver your report, then grasps the Bramblestaff with both hands.>\n\nSo, this is what the quilboar are using against us? Do you think they used these to create this jungle?", objectives = "Kill any combination of 8 Bristleback Bladewardens or Deviate Thornweavers, and collect a Bramblestaff from one of the Thornweavers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25016] = { id = 25016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Training Complete" }
quests[25017] = { id = 25017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Obstacles", description = "For years, this valley has been sealed behind impenetrable gates. Now that the cataclysm has torn them down, the secrets within are ours to discover.\n\nThere are yet some obstacles in the way. From within the gates, the bygone creations of the titans have awoken. They wander aimlessly across the sand, attacking any who approach.\n\nSomeone needs to destroy the golems patrolling the valley; are you up to it?", completion = "Thank you, {class}. We would be hard pressed to face such enemies without your assistance.", objectives = "Destroy 6 Sandstone Golems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25018] = { id = 25018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andoren Will Know", description = "Listen carefully, {name}. I don't know how those ogres got ahold of it, but that thing's a titan artifact. I'm no expert, but just that fact alone makes it probably older than the sand we're standing on.\n\nI also know that things like this are nothing but trouble. I don't want anything to do with it. Take it south, to the Valley of the Watchers, and give it to a blood elf named Andoren Dawnrise there. And don't ask any questions, babe, please.", completion = "Of all the...you found this in an ogre den? Unthinkable. I'm amazed they didn't try to smash it to pieces.\n\nWith any luck, {class}, we'll be able to obtain even more fascinating antiquities here...if you're willing to help.", objectives = "Deliver the artifact to Andoren Dawnrise at the Valley of the Watchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25019] = { id = 25019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laying Claim", description = "We are not the only ones who have discovered the value of the Southmoon Ruins. The dwarves of the Explorers' League have swarmed there, taking artifacts and inscriptions for the Alliance.\n\nI don't think I have to explain much further. We will not allow the discoveries here to fall into the hands of the Alliance. Slay as many dwarves as you can, and drive them from the ruins!", completion = "Excellent. The less interference from the Alliance, the better.", objectives = "Kill 10 Dwarven Archeologists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25020] = { id = 25020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragments of Language", description = "At the Southmoon ruins, just east of here, we've made some finds. My colleagues have found stone shards, engraved with ancient writings, newly exposed by the shifting sands.\n\nThe writings are in no known tongue, though they bear resemblance to markings we've seen on other ruins of the titans. Deciphering them could reveal many more secrets.\n\nUnfortunately, my colleagues are also busy defending the tablets from the Alliance. I need you to go to the Southmoon ruins and retrieve the tablets yourself.", progress = "Do you have the tablets?", completion = "Thank you, {name}. With that dealt with, we can focus our attentions fully on exploring the gateway.", objectives = "Collect 5 Ancient Hieroglyphs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25021] = { id = 25021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood to Thrive", description = "To survive in de harsh desert, de Sandfury had to learn all de secrets of blood magic. You drink de blood, you get de power...darkest voodoo, yah? But dere be no room for holdin' back out here.\n\nIf we gonna find de sword, we need blood. Lucky for ya, Mazoga be a traitor, yah? And dere be plenty of Sandfury trolls wanderin' over de hills dere.\n\nGo an' get Mazoga blood...plenty of blood...and we make de ritual to find Jang'thraze.", progress = "Ya ain't been drinkin' it yaself, eh? I need all of it...", completion = "<Mazoga gathers the pile of blood in his hands and raises it to his mouth. It liquifies and pours gorily down his throat.>\n\nDey drink de blood, dey get de power. I drink dere blood...\n\n<Mazoga gives you a wide, blood-smeared grin.>", objectives = "Collect 6 Fistfuls of Blood from Sandfury Trolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25022] = { id = 25022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Failure to Communicate", description = "I told him he was a fool, but Ambassador Gaines insisted he could negotiate an alliance with the quilboar against the Horde. Even if he succeeded, I for one wouldn't want to fight with those ... pig-men at my side.\n\nWell, Gaines hasn't returned, and General Hawthorne will hold me accountable if I lose one of our best negotiators to these squealing savages.\n\nLocate the Ambassador in this steaming mess of a jungle and rescue him if he's still alive.", completion = "Good work. Gaines passed through here not long ago on his way to Northwatch and a warm bath.\n\nThe mission wasn't a total loss, though. We've learned a good deal about these quilboar and their leadership structure.\n\nNow we can handle things ... MY way.", objectives = "Rescue Ambassador Gaines from the quilboar in the Overgrowth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25024] = { id = 25024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repel the Paratroopers", description = "The Alliance have caught back up with us at just the wrong moment, my friend. We took care of their ships, but they still have planes that are dropping their vaunted 127th Paratroopers onto the coast below.\n\nIt's all that the battlesworn and scouts can do to hold the two ramps against their overwhelming numbers. I'm certain that if you were to aid them, the tide would quickly be turned.", completion = "I've not seen a finer display of {class} prowess.", objectives = "Slay 10 Alliance Paratroopers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25025] = { id = 25025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sang'thraze the Deflector", description = "The blood speaks. I can feel its flow through the sand...drenched in death, a desert of suffering...\n\n<Mazoga's eyes roll back in his head.>\n\nThere! The blood flows to the south, in a valley of bones. Zakkaru! Zakkaru, spawn of Makkari, the dark one who demands sacrifice... his father forced from Zul'Farrak, his ascension interrupted... he will taste blood once more...\n\n<Mazora reels.>\n\nGo, {class}. Zakkaru has Sang'thraze. Ya not be wanting him to keep it, trust me.", progress = "Did the spirits speak true, mon? You got it?", completion = "<Mazoga grins as he takes the sword from you in both hands.>\n\nDidn't like ya much, eh? More in this world craves blood than just trolls, mon.\n\nLet's find the other blade...", objectives = "Defeat Zakkaru and collect the Sealed Sang'Thraze.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25026] = { id = 25026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkest Mojo", description = "Jang'thraze eludes me, mon... de blood is not enough. We gonna need somethin' stronger to find it.\n\nWhen you need every troll you got to help out to scrape by, one o' them dyin' on ya is a big problem, mon, an' dat's why de Sandfury learned to raise our dead wit' da voodoo. You fall over, you just get back up again and keep workin'... forever!\n\nDe zombies we make be imbued wit' darkest mojo. You go on to de west an' find a whole mess o' dem, an' get me dat mojo, yah?", progress = "You got de stuff, mon?", completion = "<Mazoga tilts his head back and inhales the clumps of mysterious material. His eyes flash.>\n\nPowerful stuff, mon...ah, if ya could see what I see now...mebbe you go try it yaself sometime.\n\nThe spirits call...", objectives = "Collect 6 Darkest Mojo from Sandfury Zombies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25027] = { id = 25027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Flicked a Fine Vine to Leaf Me", description = "According to Gaines, \"Three-Tooth\" is what the quilboar call their matriarch. She's been twisting the thorns of this crazy jungle to her own ends, and it was her orders that Gaines be \"torn apart and fed to the overgrowth.\" Nice lady.\n\nLet's give her a taste of her own. Take the Bramblestaff you recovered, and use it on Three-Tooth to take her out of the picture. Then kill the crones she's been training, to ensure nobody else can take her place.", progress = "I can see why the Horde hates these little nuisances. Have you taken on Three-Tooth yet?", completion = "...Torn limb from limb!? Well, I'd almost feel bad but the burning hatred gets in the way. She got what she deserved.\n\n<Corporal Teegan takes the Bramblestaff and snaps it over his knee.>\n\nProblem solved.", objectives = "Use the Bramblestaff on Three-Tooth and kill her 2 Deviate Crones in the Overgrowth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25028] = { id = 25028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble From the Ground Up", description = "Teegan's a fool to think the quilboar caused this sudden overgrowth. Look around you. I've been watching these plants bloom and sprout daily - each generation is more mutated than the last. This isn't tribal magic - it's something primal. And dangerous.\n\nThe day before last a great druid passed through our camp. Seek out Naralex, somewhere in the midst of this jungle. He'll know what to do.\n\nAnd bring him some plant samples from around the overgrowth to help his studies.", progress = "I am very busy, {class}. This uncontrolled growth threatens to engulf the continent. Do you have any news?", completion = "Ah, samples from different parts of the overgrowth? These will be immensely helpful, yes. Thank you, {class}.", objectives = "Gather 10 Unusual Flower Buds from Budding Flowers in the overgrowth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25029] = { id = 25029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deaths in the Family", description = "The Agamand family was the most prosperous family in Tirisfal Glades.  I used to work their mills...before the plague.\n\nWhen the Scourge first came, the Agamands fortified their home and convinced those in their employ to remain and help them defend.  We were fools, but at least we were loyal fools.\n\nThe Agamands, in their pride, doomed us to undeath.  And now they are minions of the Scourge!\n\nServe the Forsaken by defeating the Agamands who fell to the plague.  Serve me by bringing me their remains.", progress = "Do you have the remains of the Agamands?  Are those cursed beasts finally destroyed?", completion = "Revenge has a sweet taste, don't you think?  When you destroyed the Agamands, did you catch any hint of free will within them?  I hope so.  I hope they knew fear before they were smashed into oblivion.\n\nIt is a foolish hope, I know.  But it is a hope I foster nonetheless.", objectives = "Obtain Gregor's Remains, Nissa's Remains, Thurman's Remains, and Devlin's Remains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25030] = { id = 25030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Haunted Mills", description = "You sense a malign presence coming from within the skull of the beast.  Coleman Farthing may be interested in seeing this.", progress = "Well well... what do we have here?", completion = "Is this Dargol?  He was vicious even in life, with a temper that bit deep and a blade that bit deeper.\n\nUndeath has not done him any favors, though it suits his personality.\n\n<Coleman holds the skull up and peers into the empty eye sockets.>\n\nYes, this was certainly Dargol.  I can sense his malice, even from the remains you've fetched.\n\nYou have my thanks, {name}.", objectives = "Bring Dargol's Skull to Coleman Farthing at the Agamand Mills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25031] = { id = 25031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head for the Mills", description = "The Agamand Mills, to the west, have been lost to the Scourge.  The Agamand family has been slain, and the entire residence has been claimed by the Scourge.\n\nThis is probably the largest Scourge outpost in Tirisfal, {name}.  If you think you're enough of a {class}, head up there and speak with Coleman Farthing.  He's been doing his best to take the land back, and he'll need help.  Just follow this road, it'll take you right to him.", completion = "Argh!  Get back!  Oh, you're not Scourge, are you?\n\nThank the Banshee Queen that you're here.  I've greatly underestimated how bad it's gotten up here.", objectives = "Report to Coleman Farthing at Agamand Mills in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25032] = { id = 25032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets in the Oasis", description = "Yes, I see the other half now, mon...to the south...\n\nWe be close now, mon. It's in an oasis, buried in de muck beneath de water. Don't delay!", progress = "Don't be gawkin' here at me all day, mon. Best get goin'.", completion = "Mazoga? He's taken the sword? That filthy...\n\n<Trenton glowers for a moment.>\n\nAt least you escaped with your life. The Lasher's bite is a vicious one.", objectives = "Search for Jang'thraze the Protector.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25033] = { id = 25033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Red Messenger", description = "Reports from my superiors in Brill indicate that an agent of the Scarlet Crusade was dispatched from the Scarlet Monastery and sent here to Deathknell. According to the reports, the messenger possesses important information on his person. I do not have further details, but whatever it is, we must have it!\n\nYou're the most qualified person I have to send, {name}. Find that messenger and bring me whatever information you can find.", objectives = "Kill Meven Korgal, the messenger, at the Crusader camp, and obtain any information you can find.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25034] = { id = 25034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Front!", description = "I'd love to keep you here behind the lines, but it looks like you've been summoned to the front. Ambassador Gaines - remember him? - has relocated to Forward Command and in his latest missive he's requested you, personally, to assist him.\n\nYou'll find our Forward Command operation south of here, in what's become known as the \"Fields of Blood.\"\n\nBe careful, {name}. The Horde has taken to ambushing some of our officers en route.", completion = "Ah, {name}! I've been talking you up to the General here. Thank you again for saving my life.", objectives = "Locate Ambassador Gaines at Forward Command in Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25035] = { id = 25035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Line", description = "Vol'jin be callin' for an all out attack on da naga that have taken over our northern isle. Many of our men were already engaged with their forces near da bridge, but several of us are breakin' through their lines ta assault their isle itself.\n\nSpeak to Jornun right 'ere to secure a ride to da isle. Once there, seek out Morakki, da Captain of da Watch. He will be tellin' ya how ya can aid in da battle.", completion = "Good to have ya, brotha.\n\nVol'jin makes us all proud in dese moments. It feels good ta be tacklin' threats head on.", objectives = "Speak to Jornun to secure a ride to Spitescale Cove and then seek out Morakki.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25036] = { id = 25036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teegan's Troubles", description = "The Admiral will be pleased that Northwatch is almost secured, but if we're to keep a grip on this continent we're going to need to maintain the supply lines to the interior.\n\nJust before the assault I received the strangest of reports from Corporal Teegan, who's in charge of maintaining our contact with Forward Command. Says he's having trouble with the \"jungle?\" There's no jungle in the Barrens!\n\nFollow the upper road out of Northwatch and see if you can render any assistance to our wayward Corporal.", completion = "So, Paxton says there's no jungle in the Barrens? What do you call THIS!?\n\nI've got a pile of supplies to move to the interior and my camp has been overrun by a forest that - I swear - grows by the hour!", objectives = "Report to Corporal Teegan at Teegan's Expedition in Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25037] = { id = 25037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crab Fishin'", description = "Perhaps me agin' body is just growin' too picky after all dese years, but boar meat just ain't goin' down easy no more. More for da new recruits I be thinkin'.\n\nWe just set out some crab traps, but if ya be willin' ta help an impatient old troll, I'd love ta have some fresh crawler meat right now. Dey're all around da island, but da best spot ta be huntin' them is off da eastern coast.", progress = "Da sea be offerin' few boons as delicious as fresh crawler meat.", completion = "Oi! Tasty, mon. Thank ya for your great kindness, young one. Da spirits shall surely be regardin' ya with great favor.", objectives = "Kill Pygmy Surf Crawlers and collect 5 Fresh Crawler Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25038] = { id = 25038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gordo's Task", description = "Master want weeds. Us gots big hands and not good at picking. You help us and we not hurt you. Us need gloom weed. Many weeds around here and near road.\n\nWhen you have gloom weed you take to Master Holland in Brill.", progress = "Where's that useless abomination? Either you have what I need or you'd best get out there and find it.", completion = "What's this? Gloom weed?! I've no need for Gloom weed! That mindless mass of flesh is out there picking daisies and convincing the Lady knows how many dupes like you into doing the same. No offense.\n\nWe'll deal with the Gloom weed later.  For now, we've got other matters to discuss.", objectives = "Collect 3 Gloom Weed and deliver them to Junior Apothecary Holland in Brill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25039] = { id = 25039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Have You Seen Anything Weird Out There?", description = "{race}!  Listen up, I got somethin'... odd to discuss.\n\nI was out fishin' by Brightwater Lake when I saw the darnedest thing... some sorta wolf-man, running around Tirisfal.  Ya don't suppose that could be a... worgen, do ya?\n\nAnyway, I keep tellin' myself I should tell Executor Zygand about it, but I just get so scared when I talk to that guy.  Maybe you could talk with him?", completion = "Hmm... yes, that makes sense.  Since the worgen have come streaming out of Gilneas, I knew it would only be a matter of time before they arrived here in Tirisfal.", objectives = "Speak with Executor Zygand about your encounter with the worgen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25040] = { id = 25040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Worgen Attacked" }
quests[25041] = { id = 25041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lion's Pride", description = "Respect the lion, {name}! A ferocious killer. You gotta admire the elegance of the beast... Muscle and claws... Running down its food... So primal...\n\nI'm sorry, my mind wandered. As I was saying, I respect these lions, but they're just murder on our patrols. I mean that literally. The men are afraid to go to the bathroom alone at night. Can you help make our camp a little safer?\n\nBarrens lions like to linger under trees.", completion = "Nice work! How was it? Did you enjoy the hunt?\n\nDid you run through tall grasses, the scent of your prey urging you forward, until you leapt at its throat, adrenaline surging as your slavering fangs... Well, something like that.", objectives = "Kill any combination of 5 Plains Prowlers or Plains Pridemanes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25042] = { id = 25042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marching On Our Stomachs", description = "It's true what they say: An army marches on its stomach. And we've been marching a long way.\n\nI'm thinking if we barbecue up a few of those giant lumbering stormsnouts, we'll have enough meat to feed us for weeks.\n\nStormsnouts are big and slow, so they should be easy to kill. Except... Hey you're not carrying any metal on you are you?", progress = "<Trawley licks his lips, barely able to constrain his drool.>\n\nYou get my steaks yet? Nice and bloody?", completion = "<Sam's eyes bug out of his head as you slam the huge slabs of meat before him.>\n\nOh yeah... oh ... YES! I'll have mine raw. I suppose I can grill some up for the others... How would you like yours?", objectives = "Collect 4 Fresh Stormsnout Steaks by killing Stormsnouts in Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25043] = { id = 25043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fields of Blood", description = "The Horde has taken to calling this region the \"Fields of Blood.\" It's an apt name: these reeds run red with the blood of some of my best men.\n\nI've sent out recon patrols to crush the quilboar and report on the Horde troop movements, but not all of them return. They could use your support out there.\n\nPatrol the fields and seek out the Desolation Grunts that are causing us so much grief. Do not expect them to surrender; their Warchief has instructed them to fight to the death.", completion = "Very good. We may never drive the Horde completely from these lands, but with a strong presence we can undermine their will to fight.", objectives = "Kill 10 Desolation Grunts at the Fields of Blood in Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25044] = { id = 25044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomacy By Another Means", description = "I have not forgotten my brush with death at the hands of the quilboar in that filthy jungle. The General here has ordered some tactical strikes, but he stops short of genocide. I have no such qualms.\n\nTake this horn that I 'borrowed' during my negotiations. Blow the horn within the Bristleback challenge ring west of our position - you can't miss it. I want you to challenge the champion of the Bristleback, Sabersnout, to single combat. His death in front of his followers will leave them in utter chaos.", progress = "Sabersnout! Is he dead? What's the news?", completion = "A \"Boarpocalypse,\" you say? These animals certainly have a unique idea of \"Single combat!\"\n\nNo matter, you've done well. With the quilboar in chaos I should have no trouble convincing the field commanders to execute any strays they find scurrying about. The General need not know we've stepped up the campaign... it's for the better.", objectives = "Take the Horn of Challenge to the Bristleback Challenge Ring in Southern Barrens. Blow the horn to challenge Sabersnout and kill him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25045] = { id = 25045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Line in the Dirt", description = "Strategically, control of a region requires constant observation. See here on this map - I've identified a number of strategic hills, similar to this one, that the Alliance must acquire if we are to keep the enemy under our thumb.\n\nMy scouts have already marked their location on the field. What I need is someone to spearhead their capture, and you're the <man/woman> for the job.\n\nSeek out neutral grey flags on hills to the north, east, and south of the Taurajo Ruins. Capture one and defend it!", progress = "How goes the fight? Every inch of territory our valor earns today grants us continued security tomorrow.", completion = "Your report, {class}?\n\n\n\nIncredible, {name}! You're a real asset to the Alliance. I'll see to it that my men follow your example!", objectives = "Capture a neutral hill in the Fields of Blood and defend it against a Horde counter-attack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25046] = { id = 25046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Daughter's Embrace", description = "The whisper continues:\n\n<\"My name is Lilian Voss.  Before I died, I was a member of the Scarlet Crusade.  My father, High Priest Voss, raised me to be a weapon against the plagued.  I studied stealth, sorcery, martial arts, anything to make myself stronger.  I gave up my childhood for him.\">\n\n<\"Then, as fate would have it, I died and returned as... this.  My father instantly forgot me and, when I returned, ordered me executed.\">\n\n<\"Come.  We will speak with him now, in his tower to the northwest.\">", completion = "From birth to grave to undeath, we all have our own path to follow.  Some are easier than others.  It sounds like this Voss girl has had a rough path so far.\n\nHopefully she ultimately chooses to join us and follow the Dark Lady.  With power like hers, we could do incredible things.\n\nBy the way, {name}... excellent work out there.  If you're ever ready and willing, I may have some more work for you in the Plaguelands.", objectives = "Bring Lilian Voss to her father in the tower at Crusader's Run.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25047] = { id = 25047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Panther Figurine", description = "This badly broken figurine was discarded by its last owner.  However, with the right materials and your skill in jewelcrafting, it could be completely restored.", objectives = "Repair the broken figurine using your skill and materials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25048] = { id = 25048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seaside Salvage", description = "If we want to convince Mister Noggenfogger to let us move more gnomes here, we've got to show him just how nice we are! I know just the thing.\n\nGadgetzan's under blockade by pirates, but plenty of the goods that get blown off the ships survive intact... they just wash away. Most of them wash up in the shallows just south of town.\n\nIf you could go collect those supplies for them, it'd help us make friends! And it'll keep that mean goblin girl over there from taking them and selling them.", progress = "Do you have a whole buncha boxes? Let's see!", completion = "Most of this looks just fine! How lucky!\n\nThe Steamwheedle goblins will be so happy to see their cargo back safe and sound. And here's a reward for your good deeds, of course!\n\nWe've got lots of other stuff to do though! Busy busy!", objectives = "Collect 7 Steamwheedle Supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25049] = { id = 25049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Puddle Stomping", description = "There's a big problem here! It's great that the ocean came in so far, because now ships can get to Gadgetzan. But now there's a bunch of nasty old sea giants encroaching on the town! I'm sure Mister Noggenfogger would appreciate us taking care of them for him.\n\nDon't worry, I won't ask you to do it just out of the goodness of your heart! Take care of them and I'll give you a reward!", completion = "Oh, it's going to be so much nicer around here now that they're gone!\n\nAt least until more show up. But thank you!", objectives = "Kill 8 Tidal Striders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25050] = { id = 25050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocket Rescue", description = "When the water came in, Steamwheedle Port to the east was flooded, and a lot of poor goblins are still stuck there! Now those mean pirates are shooting at any boat that leaves the docks here.\n\nBut they won't expect us to fly! There's a hot air balloon by the docks. We can use that, fly over to rescue the goblins, and take care of the pirates, too. Mr. Noggenfogger will be so pleased!\n\nGo to the docks and hop in the balloon and I'll be right behind you, okay? I've got to get some rockets...", progress = "Let's not wait around, silly! We weren't done yet! We've gotta get out there!", completion = "That was great! It looks like most of the goblins we helped made it back here and didn't blow up. We really showed that goblin girl!\n\nHere's a special reward for you, mister.", objectives = "Deliver Liferockets to 5 Steamwheedle Survivors and use bombs to kill 40 Southsea Blockaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25051] = { id = 25051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmist Extermination", description = "The spiders that occupy Darkmist Cavern to the northwest are another vicious threat to us here. They are nothing the ogres cannot handle, but splitting our attention to them when Theramore's forces lurk nearby is a deadly mistake.\n\nI need someone to destroy the eggs inside Darkmist Cavern, to cut off this infestation. You will find the eggs in the deepest part of the webbed mines... along with their guardians.", completion = "This is a great relief, {class}. Thank you.", objectives = "Destroy 8 Darkmist Eggs in Darkmist Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25052] = { id = 25052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead Man's Chest", description = "Well gosh, as you can plainly see there's this really big battle with these pirates here going on. We're doing our best to make sure they never bother Gadgetzan or our new gnomish homes there ever again!\n\nBy killing them.\n\nSo how about helping us? We really wanna make sure we kill more than green-nose over there and her awful thugs. I'd really appreciate it!", completion = "Good job! We're really cleaning up around here!", objectives = "Kill 15 Southsea Pirates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25053] = { id = 25053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To The Ground!", description = "You know, this place would probably make a great home for us gnomes if it wasn't so old and dirty and full of pirates! We're taking care of the pirates problem, but the awful and dirty problem needs fixing.\n\nI mean, no self-respecting gnome would ever live in such an ugly hovel like these buildings! So here, take this bottle of flaming rum and go burn those ugly shacks down for us!", completion = "Isn't that just so pretty to watch?", objectives = "Use the Burning Rum to set fire to the Northwest Shack, the Northeast Shack, and the Southwest Shack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25054] = { id = 25054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lootin' Plunder", description = "It's just really so wasteful that all these pirates have golden treasures lying around. Some of this stuff could be used for practical things! Like melting into wire, or intrinsic shielding matrices, or selling to other stupid races that buy gold just to keep it around.\n\nAnd speaking of other stupid races, I bet those greedy goblins are going to be taking all of it. We can't let that happen! Go collect that treasure for Gnomeregan!", progress = "I hope you don't think you're hiding any for yourself, silly! These goggles can see right through your bags.\n\nAnd your armor.", completion = "Fantastic! Gosh, this will make enough wire for an entire army.\n\nLucky us!", objectives = "Collect 10 pieces of Pirate Loot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25055] = { id = 25055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subduing the Elements", description = "The elements are restless, {class}.  The earthquakes that plague the land and threaten to collapse Ironforge are not normal.  The Earthen Ring are convinced that we must put the elements to rest before they tear Azeroth apart.  We need your help, {name}.\n\nI will give you a bag of Earthen Ring supplies.  In it you will find two items, elemental sapta and a cleansing totem.  Use the sapta to see into the elemental world.  Then use the cleansing totem to subdue the agitated earth spirits.", progress = "Have you subdued the elements yet?", completion = "Well done {name}.  But for every element that is subdued another one takes it's place.  The solution we have here is merely a stopgap.  Hopefully my brethren in the Earthen Ring are making more headway.", objectives = "Gavan Grayfeather wants you to use the elemental sapta and cleansing totem from the Earthen Ring supplies to subdue 20 Agitated Earth Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25056] = { id = 25056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grisly Grizzlies", description = "Have you seen the plagued bruins that wander to the west of here?  Those hides... so hideous, so diseased, so... perfect!\n\nFetch me 5 of them.  I've got an idea for an anti-Scourge poison that's guaranteed to succeed!", progress = "Let's see... do you have enough hides?", completion = "Dithers, you've done it again!  These are perfect.", objectives = "Obtain 5 Plagued Bruin Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25057] = { id = 25057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clap 'Em In Irons", description = "Our policy of conscripting non-violent criminals from the Stormwind Stockades has come back to haunt us, {name}. Some of my less-scrupulous soldiers broke ranks after our victory in Taurajo and are looting the remains of the city.\n\nThis is a breakdown in discipline. Worse, the desecration of their homes only spurs the enemy to fight harder when our ultimate goal should be peace.\n\nTake these manacles and bring the Taurajo looters to justice. Speak to them first, but you may need force to subdue them.", progress = "Is the Taurajo situation under control?", completion = "Well done, {name}. Several of the looters have already crawled back, requesting clemency. I'll let them stew for a bit in the Northwatch brig.\n\nThank you for helping maintain discipline in the ranks. It is important for our army to be perceived as soldiers, not common bandits.", objectives = "Speak to the Taurajo Looters in the Taurajo Ruins and place them under arrest. Use the Northwatch Manacles to subdue 5 wounded looters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25058] = { id = 25058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mine Disposal, the Goblin Way", description = "The paratroopers have mined the beach!\n\nThe Warchief asked me if there's anything we can do about that. I told him, 'You bet we can!'. I was thinking maybe you could take this satchel of grenades and detonate the land mines from a safe distance?\n\nIt's how we do things, right?!", progress = "Boss, do you think you could go back down there and detonate a few more?\n\nThanks!", completion = "Score one for the goblins! Stupid dwarves and gnomes.", objectives = "Detonate 10 Land Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25059] = { id = 25059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Taurajo Briefs", description = "The General is too preoccupied with the looters in Taurajo. Too soft! We ought to be focused on our next move against the Horde.\n\nThere's valuable intelligence that might be compromised if we allow the ruins of Taurajo to continue to burn. While you're running the General's errand, dig around for any maps or notes you can find. I can speak a little of the orcish tongue - I'll be able to make sense of what you find.", progress = "Have you searched the ruins yet?", completion = "What have you dug up for me? Hmm. Interesting. This notice from Orgrimmar indicates a change in Horde leadership is underway - I guess heads are going to roll after what we did to Taurajo.\n\nWhat's this? A death warrant for the General here! This is good to know... Very good to know...", objectives = "Search the Ruins of Taurajo for 3 pieces of Taurajo Intelligence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25060] = { id = 25060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Define \"Crazy\"", description = "We received reports that a goblin shipwreck occured on this beach some time ago, with the survivors left to fend for themselves. We expected there to be a modicum of survivors, perhaps some even suitable for interrogation.\n\nWhat we found was a crew of Bilgewater goblins who have all become insane, delusional, and maniacally violent...to further degrees than is normally observed, rather.\n\nIn short, they are useless and dangerous. Gnomeregan will be best served by cutting down as many as we can.", progress = "I sincerely doubt you'd prefer to adjust our mechanostriders or oil my boots for spare copper instead, {name}. Go kill more goblins.", completion = "Your reports of their behavior are truly disturbing...but also slightly amusing.\n\nIf only that Dreadshredder wench had escaped on these vessels instead...", objectives = "Kill 10 Crazed Survivors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25061] = { id = 25061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Land's End", description = "Psst! Hey! Come closer, you fool, you expect me to read your mind or--oh. Come closer anyway!\n\nYou've done a wonderful job advancing the agenda of Gnomeregan here, friend! And an amazing job of pretending you were only in it for the coin, simply splendid. But now Kelsey Steelspark could use more of your direct help.\n\nShe's moved on yet again...she asked me to tell you to meet her far south, at Land's End Beach. I wouldn't keep her waiting, either!", completion = "I'm amazed that Soothfancy was capable of following a simple set of instructions. And ones that required him to keep his foolish mouth silenced as well.\n\nIn addition, it is honestly good to see you again, {name}. Now that I've dropped the charade, you'll get to see how gnomes get things done around here.", objectives = "Talk to Kelsey Steelspark at Steelspark Station.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25062] = { id = 25062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What We Came For", description = "Gnomeregan previously learned that the Bilgewater goblins of the Horde survived a crash on an uncharted island near Kalimdor before arriving in Durotar. We initially came here to investigate what techniques and technology could possibly allow a hopeless pack of imbeciles to survive such harsh conditions.\n\nWhile the goblins are at a loss, we still need to find out exactly what happened here. Search the beach for wreckage and belongings and bring anything that appears significant back to me.", progress = "What have you found?", completion = "<Kelsey takes the journal and gingerly flips through it.>\n\nI'm trying not to laugh. This is classic. They have no idea they're even on Kalimdor!\n\nThese later pages though...something more significant may be occuring here.", objectives = "Search Bilgewater Footlockers for evidence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25063] = { id = 25063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrapination", description = "We need to obtain the object described in this journal, for certain. Extracting it from a chest would be a feasible matter, but the object itself sounds compromised, and unstable. Attempting to forcefully open the chest could be disastrous.\n\nFortunately, we know where the key is...statistically speaking, at least. There's plenty of sea turtles at the east end of this beach. One of them may hold the key.", progress = "Hopefully your spree of turtle destruction left it intact.", completion = "Well, gosh, this day just keeps getting better and better! I may actually smile.\n\nWhen you're not looking. You've seen enough of that already.", objectives = "Obtain a Turtle-Digested Key from a Surf Glider.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25064] = { id = 25064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moraya", description = "Moraya has been lookin' for some help with tha raptors. Ya should talk to her on the other side of Darkspear Hold when ya get a chance.", completion = "Hey there, hon. Vol'jin sent you? So sweet of him to be thinkin' of me.\n\nI surely could use da help, but ya have a bit more walkin' ahead of ya.", objectives = "Speak with Moraya.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25065] = { id = 25065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Too, Brute?", description = "It's time to conclude this matter efficiently. From what we've determined, this mysterious object is in the possession of the \"smart\" brute described in the journal. We don't know exactly what's happened to this creature, obviously, so you should take caution.\n\nThis... \"Meatface\" is hiding in the hills, near where these goblins bury their dead. Look for the graveyard and he should be just past it.", progress = "Do be careful with the contents of the chest.", completion = "Well done, {name}. The contents of this chest are sure to advance Gnomeregan's knowledge base significantly. I believe you've earned a reward.", objectives = "Obtain Meatface's Chest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25066] = { id = 25066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pride of Kezan", description = "This is ridiculous! Those gnomes just don't know when to stop!\n\nGoblin pride is on the line here! {name}, you gotta jump into the Pride of Kezan and show them what's what!\n\nLet me know when you're ready!", progress = "What are you doing back here? Get up there and shoot them down!", completion = "YES!", objectives = "Shoot down 10 Gnomeregan Stealth Fighters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25067] = { id = 25067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderdrome: The Ginormus!", description = "The rules are simple: Two men enter, one--wait. Sometimes there's women.\n\nTwo people enter, one--Wait, no, sometimes it's more than two...and that means more than two come out--\n\nAlright, only rule is stay in the drome! There are no other rules!\n\nYou're up against the biggest, baddest member of the Wastewander Bandits first. This'll either be a warmup or a bloodbath...it's up to you which!", progress = "Stop wasting my time. Enter and fight!", completion = "An impressive start. Be prepared for more.", objectives = "Defeat Lord Ginormus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25068] = { id = 25068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crumbling Past", description = "The creatures wandering these ruins are Earthen, the ancient ancestors of dwarves, made by the Titans to shape the world itself.\n\nThe original Earthen broke down and went awry thousands of years ago, and these freshly uncovered ones seem no different. We may as well make use of these confused and unstable constructs.\n\nEnter the ruins and destroy the Earthen, and collect the jewels embedded in them; their magical energies will be both valuable and worthy of study.", progress = "Handle those carefully, {name}; they are as ancient as the world itself.", completion = "Marvelous. To think the shapers of our world crafted these...", objectives = "Collect 5 Earthen Jewels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25069] = { id = 25069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secrets of Uldum", description = "We are ready to enter the antechamber itself, {name}. This is a momentous occasion.\n\nFrom the writings you've brought us, I believe these ruins were in fact once the grand entrance to Uldum itself. The quakes that ripped its doors open have probably collapsed the tunnels, but we may yet find amazing things hidden within.\n\nSearch the ruins for anything intact that may be studied.  The thrill of discovery awaits!", completion = "This chest lies undisturbed, sealed for thousands of years.", objectives = "Search the Antechamber of Uldum for an intact artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25070] = { id = 25070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Lies Within", description = "As you lay your hand upon the chest, a faint rumbling can be heard. The sound of grinding movement echoes behind you as the chest begins to shut itself.\n\nSomething is approaching!", completion = "The chest now grinds open again, the rest of the antechamber fallen silent.", objectives = "Defeat the Antechamber Guardian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25071] = { id = 25071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Purple Murloc" }
quests[25072] = { id = 25072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Few Good Goblins", description = "We haven't just been camped here singin' songs with gnomes and playing with dangerous machinery, you know. My men have been trying to clear this hive out for a week now! Problem is, we've taken so many losses by now that the bugs have the advantage.\n\nLucky for us, the bugs either don't like to eat goblins, or they like us so much they save us as treats, because nearly all my men are still cocooned up out there. I need you to go save 'em.", completion = "Thanks for the help, this was really killin' things here. Once you start losing men, you start losing manpower. And morale. And weapons. And the magazines you loaned to that one guy.\n\nYou know how it is.", objectives = "Save 8 Captured Goblin Bughunters from Hazzali Cocoons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25073] = { id = 25073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sen'jin Village", description = "You've be doin' quite well for one so young. I've no doubts you'll be makin' quite da name for yarself.\n\nGo now, northwest, across da shallows ta Sen'jin Village. Dere you'll be meetin' Master Gadrin. He'll likely have a task or two for ya before ya truly make ya way out into the Durotar wilds.\n\nPlease remember, {name}, we may disagree wit' the young Hellscream at times, but his intentions are noble, and it be very important that we remain united as one Horde. Make da Darkspear proud.", completion = "Welcome, young {race}.\n\nYa come highly recommended, mon. It's nice ta finally be meetin' ya in person.", objectives = "Report to Master Gadrin in Sen'jin Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25074] = { id = 25074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Me at Triumph", description = "Thanks in part to your efforts, we've stabilized the situation here. We need to turn our attention south, to Fort Triumph.\n\nFort Triumph is the keystone of our operation in the Barrens - the vital land-link between Northwatch and Theramore.\n\nI'll pack up and head out separately. Report to Commander Roberts at the fortress and I will see you there soon. Together, we will secure the frontier!", completion = "Have you heard? The General never made it!\n\nKilled in the field, like some kind of dog!", objectives = "Report to Commander Roberts at Fort Triumph in Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25075] = { id = 25075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pick-a-Part", description = "These bulky dwarven siege engines aren't cut out for the close-quarters fighting of the Battlescar.\n\nI've got some new designs I'd like to try out, but first I'm going to need some spare parts. There's plenty of wreckage sitting in the Battlescar. All I need is an enterprising {class} to haul it back for me.\n\nThat's you, {name}. I'm talking about you.", progress = "What have you got for me?", completion = "Oohh look! A mostly complete exhaust manifold, a reciprocating junction box, a working counterweight slip differential ... you sure know your junk, {name}.", objectives = "Collect 8 Siege Engine Scrap pieces from the Battlescar in Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25076] = { id = 25076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "You have spent your young career mastering the arts of single combat.  I feel it is high time that you learned a new form of combat - that of the trained pet.\n\nTake this rod and use it on a vampiric duskbat until it joins you and your cause.  It may take you some time, but I have faith that you can bend the bat to your will.", objectives = "Use the Taming Rod to befriend a Vampiric Duskbat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25077] = { id = 25077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "Lately we have seen some young, plagued bears passing over the mountains between here and the plaguelands.  While these bears' trek into Tirisfal tests and threatens the defenses that we have laid at the Bulwark, their passage is a blessing to us hunters.\n\nProve to me you learned something from our last lesson, and use the rod on a plagued bruin, far to the east.", objectives = "Use the Taming Rod to befriend a Plagued Bruin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25078] = { id = 25078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "Your final test involves the spiders that reside in Venomweb Vale, north of the Bulwark.  Yes, even these simple creatures can become a valuable trained ally.  I have seen many hunters that count these venomous creatures as part of their arsenal.\n\nUse the rod to tame one, and return to me when you finish.You will learn:", objectives = "Use the Taming Rod to befriend a Vicious Night Web Spider.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25079] = { id = 25079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Powder Play", description = "Our shipments of saltpeter from Dustwallow have been held up, which means we can't manufacture our own gunpowder here.\n\nBut I can retrofit our armaments to use goblin Blast-O powder. It's unstable, dangerous, toxic to the skin, and harmful if swallowed... but I think I can make it work!\n\nGet me a keg of the stuff by attacking one of those goblin sapper specialists who've been storming our walls.", progress = "Do you have a keg of Blast-O powder yet?\n\nWhen you get one ... don't shake it.", completion = "Great! Set the keg down right here. I'll measure out some charges once I've donned my full-body protective gear.", objectives = "Defeat a Sapper Specialist near the Battlescar and acquire a Keg of Blast-O Powder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25080] = { id = 25080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Batteries Not Yet Included", description = "Okay! Using the spare parts you've found for me, I've got a framework roughed out for my versatile new assault vehicle. All I need now is a compact power supply.\n\nI've noticed that the indigenous wildlife here packs quite the punch, electrostatically speaking. Can you hunt down Thunderheads near the base here and get me an intact electrogizard? It might take a few kills to find a usable gland.", progress = "It must be an enormous evolutionary advantage to be able to shoot lightning. From your face.", completion = "<The gizard shocks Mizzy as you hand it over, blasting her to the ground.>\n\nOh, OH! That's nasty! I love it!", objectives = "Acquire a Humming Electrogizard from a Thunderhead in Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25081] = { id = 25081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claim the Battlescar", description = "The Horde has fought us to a standstill from their stronghold west of here. The fighting continues, even as the land breaks open under our feet.\n\nSomeone's got to break the stalemate! I need you to venture into the Battlescar and help my men crush the Horde opposition there.\n\nIn the center of the scar you will find a flag marker designating who controls the area. Scout out the flag. It'll be worth your while to claim the scar for the Alliance if someone hasn't already done so.", completion = "Incredible work, {name}! My men report a breakthrough. Their stronghold won't survive much longer...", objectives = "Go to the Battlescar. Scout out the flag marker and kill 10 Desolation Raiders.\n\nCapturing the flag will give all Alliance players in the scar a combat advantage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25082] = { id = 25082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Working the Bugs Out", description = "Why high command decided that a silithid mound was the ideal place to build a fortress, I'll never know. Them lil' buggers are tunneling under our fortifications and setting back our timetables. We need to scorch 'em out!\n\nTake this here bucket of burning pitch and dump it on the silithid mounds right outside the main gate. They look like big piles of sand. Kill anything that comes out, but be careful, {name} - them nasties are likely to swarm you when you light those mounds up.", progress = "How goes the fight, {name}?", completion = "That oughta take care of our bug problem for a while - they'll be hard-pressed to tunnel their way outta that!", objectives = "Use the Bucket of Burning Pitch on the silithid mounds outside of Fort Triumph to flush out and kill 10 Silithid Swarmers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25083] = { id = 25083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beast Training", description = "One last thing, <hunter/huntress>.  You'll want to speak with Apolos at the Undercity.  He'll teach you the last few bits of knowledge necessary to care for and train your pet.\n\nYou can find him in the War Quarter.", sourceObjective = "Speak with Apolos in the War Quarter of the Undercity.One last thing, <hunter/huntress>. You'll want to speak with Apolos at the Undercity. He'll teach you the last few bits of knowledge necessary to care for and train your pet.\n\nYou can find him in the War Quarter.", sourceObjectiveStatus = "unverified-source-field" }
quests[25084] = { id = 25084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Growing Threat", description = "A moment there, {class}.\n\nWe've got more problems here than just the end of the world as we know it. Our vigil here's threatened by the quilboar. We've been content to leave them be when they stay in the Kraul, sure, but every day they press further and further out towards our camp.\n\nMahka, bless her green heart, wouldn't ever forgive me if I went out bashing heads in myself, but if you could help drive back those that're wandering near the camp, I'd appreciate it.", completion = "You've my thanks, if not that of the entire Earthen Ring.\n\nMaybe someday we'll find a way to talk it out with these pigs, but we can't heal the land if we're dead in our sleep.", objectives = "Kill 13 Razormane Quilboar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25085] = { id = 25085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mangletooth", description = "Una here used to spend time in Camp Taurajo. She's told me about a quilboar that used to be captured there, named Mangletooth. Quite the clever one, for a quilboar.\n\nI've been tryin' to think what got these quilboar riled up so much recently, and it might be that Mangletooth escaped Taurajo alive. If he has, he's certainly calling the shots.\n\nThere's a large hut up in the hills to the northwest. If you find Mangletooth there, cut 'im down.", progress = "Did you find him?", completion = "That's a relief. Maybe the rest of 'em will keep to their own devices now. The less fighting around here, the better.", objectives = "Kill Mangletooth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25086] = { id = 25086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firestone Point", description = "Can you do me a huge favor, {name}? My sister-in-law's uncle is in the Earthen Ring, and he's here in the Barrens studying the impact of the Cataclysm, down at Firestone Point. He says their camp is surrounded by quilboar and I worry that they might get overrun.\n\nCan you check in on Dorn Redearth for me? I'd hate for anything to happen to him, what with the close family bond and all.", completion = "What? Little Logan thinks I might need protection?\n\nIt's me doing the protectin'!\n\nThe quilboar here are poised to rampage. They've choked off the entire south, and we're the only thing standing in their way.", objectives = "Seek out Dorn Redearth at Firestone Point in Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25087] = { id = 25087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Twinbraid", description = "The Alliance owes a debt to the dwarves of Bael Modan, who built some of our earliest fortifications in the Barrens.\n\nTheir commander, General Twinbraid, is a real stalwart. One of our best. He's on patrol south of here, keeping the Horde on their toes.\n\nI definitely want to keep him appraised of the situation here so we can coordinate our next move. Can you deliver this frontline report to him in the field?", progress = "Hrm, news from the fortress? Well. Spit it out!", completion = "<The General reads over the report, nodding in approval as he reads about the Battlescar.>\n\nQuite a name you're earning for yourself here in the Barrens, {name}. But Roberts isn't going far enough. What we need is a decisive victory...", objectives = "Deliver the Frontline Report to General Twinbraid, who is on patrol in Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25089] = { id = 25089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beyond the Graves", description = "Darnell tells me that the two of you have already met.  That's good, because I'm sending you both into Deathknell.  Your work is done here.\n\nSpeak with Deathguard Saltain in Deathknell, to the north.  He will tell you more of what you must know.", completion = "Those val'kyr have been really busy resurrecting you newbies lately.  I've already seen a couple dozen new bodies run down that hill since this morning.\n\nYou, however, are the most promising {class} I've seen today.", objectives = "Speak with Deathguard Saltain at Deathknell in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25090] = { id = 25090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Putrid Task", description = "Scourge have trickled into Tirisfal Glades and have infested this area.\n\nI need someone to beat back the rotting dead and ravaged corpses that have taken this small farm.  Scatter their bones and bring back their putrid claws.  The Deathguards will reward you.", progress = "Have you completed the task with which I have charged you?  Do you have those putrid claws?", completion = "Well done.  I enjoyed watching you smash those {race} into rotting pulp!", objectives = "Bring 7 Putrid Claws to Deathguard Dillinger in Cold Hearth Manor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25091] = { id = 25091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandsorrow Watch", description = "If you're looking for more work, I've got a line for you.\n\n I know an elf by the name of Trenton Lighthammer who's been obsessed with the sand trolls near here for years. He's dead-set on finding some kind of mythical sword made by them, and just a while ago he finally got a crew together to go to Sandsorrow Watch and look for it.\n\nLast I heard, they kicked the trolls out of one of their camps and set up shop there. Look for it to the west, near Zul'Farrak.", completion = "Marin sent you? I'm appreciative of his help.\n\nI'm here to seek out Sul'thraze. If you wish to help, speak with Mazoga...he's been cooperative so far.", objectives = "Speak with Trenton Lighthammer at Sandsorrow Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25092] = { id = 25092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subduing the Elements", description = "The elements are restless, {class}.  The earthquakes that plague the land and the fires that threaten to burn down Orgrimmar are not normal.  The Earthen Ring are convinced that we must put the elements to rest before they tear Azeroth apart.  We need your help, {name}.\n\nI will give you a bag of Earthen Ring supplies.  In it you will find two items, elemental sapta and a cleansing totem.  Use the sapta to see into the elemental world.  Then use the cleansing totem to subdue the agitated fire spirits.", progress = "Have you subdued the elements yet?", completion = "Well done {name}.  But for every element that is subdued another one takes it's place.  The solution we have here is merely a stopgap.  Hopefully my brethren in the Earthen Ring are making more headway.", objectives = "Seer Bahura wants you to use the elemental sapta and cleansing totem from the Earthen Ring supplies to subdue 20 Agitated Fire Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25093] = { id = 25093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heads of the SI:7", description = "These orcs were murdered in cold-blood by the Alliance down on the coast. We did nothing to provoke them.\n\nTheir deaths should not be in vain, {name}. Will you bring them justice?\n\n<Aggra appears as if she can barely contain her rage.>\n\nThere are three SI:7 leaders down there along the beach. Bring me each of their heads.", progress = "Has justice been served?", completion = "Thank you, {name}. The spirits of the fallen can now be put to rest.", objectives = "Collect the heads of Commander Arrington, Darkblade Cyn, and Alexi Silenthowl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25094] = { id = 25094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderdrome: Zumonga!", description = "Splendidly done! But you'll be fighting more than mere humans!\n\nYour next opponent's a mean one...watch out for his right hook. And his left. I'd be wary of his fists in general.", completion = "Not bad. You've got a ways to go, however.", objectives = "Defeat Zumonga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25095] = { id = 25095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderdrome: Sarinexx!", description = "I hope you're ready for the next one, {name}. One mistake could mean instant, painful death! But that's what the people pay to see, isn't it?\n\nI hope you're not afraid of bugs...", progress = "Stop wasting my time. Enter and fight!", completion = "Rather impressive. Few can bear to see a silithid reaver face to face, let alone defeat it.", objectives = "Defeat Sarinexx.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25096] = { id = 25096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderdrome: Prince Mosh!", description = "We're gonna have to bring out the big guns to top that last fight!\n\nDon't worry, my friend, we've got more blood for you to spill. Many goblins died to capture the next fighter...he's a whopper!", objectives = "Defeat Prince Mosh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25097] = { id = 25097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Little Sumpthin'", description = "Lissen, pal.\n\nI got a friend, who knows a fella, who might just be lookin' for a {class} that knows <his/her> way around a fight.\n\nIf you're not afraid to get your hands dirty, head south over the mountains and look for a goblin named Vern.\n\nTell him Drazz sent ya...", sourceObjective = "Drazzit Dripvalve wants you to talk to Vern Futzwidget in Thousand Needles.", sourceObjectiveStatus = "unverified-source-field" }
quests[25098] = { id = 25098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warchief Wants You", description = "True to his word, Thrall is going to get us going in the right direction to rescue our people. He asked to speak with you.\n\nGood luck, {name}. We're all depending on you.", completion = "Once again you have helped us to overcome our mutual enemy, the Alliance.\n\nNow it is time for us to help you.", objectives = "Speak with Thrall at the Warchief's Lookout on the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25099] = { id = 25099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borrow Bastia", description = "Head back down to the coast and tell Kilag that I'd like for you to borrow Bastia. The panther knows the way to where your friends are being held captive.\n\nGo now. I will see you again before we make our move against the Trade Prince.", completion = "Of course you can borrow Bastia. That is, if she'll take you.\n\n<Kilag winks.>", objectives = "Speak with Kilag Gorefang at the Tranquil Coast on the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25100] = { id = 25100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's Ride", description = "Bastia will make sure that you get to where you need to go, goblin.", completion = "{name}?! Nice kitty.\n\nLook we don't have much time here. You might have noticed that the volcano is blowing?!", objectives = "Speak with Slinky Sharpshiv at Sky Falls on the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25101] = { id = 25101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friend of a Friend", description = "Say, you look like a frisky sort...\n\nI know a guy who knows a fella that might be lookin' for a {class} who knows <his/her> way around a fight.\n\nIf you're not afraid to get your hands a little dirty, make your way south across the mountains and look for a goblin by the name of Vern.\n\nTell him Smiling Jim sent ya.", sourceObjective = "Smiling Jim wants you to talk to Vern Futzwidget in Thousand Needles.", sourceObjectiveStatus = "unverified-source-field" }
quests[25102] = { id = 25102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Bull", description = "Twinbraid's patrols always throw us right into the thick of danger. If it's not Horde ambushes, it's a quilboar hit-and-run.\n\nThe problem is them lousy landquaker kodos. Big walkin' walls of fur, shakin' the ground... We can't see or hear an ambush creepin' up on our backside.\n\nGo scare 'em off from our patrol, here. Killing a few should drive the herd south and out of what's left of me hair.", progress = "Good to see you're not squished.", completion = "I thought you might be responsible for them clouds of dust I saw to the east. Nice work! Them bulls ain't sissies.", objectives = "Kill 4 Landquaker Kodos and 1 Landquaker Bull in Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25103] = { id = 25103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bootlegger Outpost", description = "We've done a bang up job here. I'm gonna make sure these mooks finish properly and then head back to Gadgetzan for a bit.\n\nIf you want to keep making a good impression on our Steamwheedle friends, or just make more money, you should head southwest of here. Bootlegger Outpost is set up on the edge of the gaping chasm.\n\nTalk to Zeke Bootscuff. I'd bet good money he'll need help.", completion = "You're with Megs, huh? Word is she's been pretty hell-bent on making nice with Noggenfogger.\n\nNot like I care. Are you ready to kill some bugs?", objectives = "Talk to Zeke Bootscuff at Bootlegger Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25104] = { id = 25104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Digsite Status", description = "The patrol's been quiet today. And that's got me worried, {name}.\n\nEver since the Alliance sacked Taurajo, none of our positions are secure. You look like you can handle yourself - can you scout around for me?\n\nCheck in with my son Marley outside the Bael Modan excavation, southeast of here. The site's exposed and susceptible to raids, and my son's too proud to signal for help if he needs it.", completion = "Father sent you? He worries too much. There's nothing here I can't handle...\n\nBut I'd still appreciate the help.", objectives = "Locate Marley Twinbraid outside the Bael Modan Excavation in Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25105] = { id = 25105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nibbler! No!", description = "Lila's pet Nibbler got into my workshop again!\n\nI was making a bracelet, to be delivered today.  The work was almost done, except for the gems.  I spent all night cutting them, but when I stepped out for a bit of breakfast, the little beast came into my workshop and swallowed every gem in sight!  The thing can digest ANYTHING, and trust me, you'd break your back trying to pick up its leavings.\n\nI need to get replacement gems fast; the courier is coming in tonight.  Help!", progress = "Have you brought the solid zephyrites I need?", completion = "You've really saved my skin, {name}.  Thanks!", objectives = "Cut three Solid Zephyrites and give them to Isabel Jones in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25106] = { id = 25106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hands Off Me Dig!", description = "Look at the chaos down there, {name}! I've instructed the foremen to save what artifacts they can. Who knows what treasures these tauren animals are like to make off with.\n\nCan you help get a handle on things? Kill the raiders and save what artifacts you can.\n\nWhile you're at it, look for my missing tools. A few quick repairs and I can get this flying machine up and running again.", progress = "How's the situation down there?\n\nWhen the raid started I popped a bullet into their ringleader, Stonespire, but they just kept right on coming.", completion = "My father would be proud of you, {name}.\n\nNow, to get this flying machine up and about again...", objectives = "Kill 8 Excavation Raiders, rescue 5 Bael'modan Artifacts, and acquire Twinbraid's Tools in the Bael'modan Digsite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25107] = { id = 25107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Tablet", description = "At the bottom of the chest, you find a large tablet. Made of a material resembling stone, but completely smooth and flawless, it is covered in strange writing.\n\nWhile some resembles the writing on the walls, other scripts appear completely different. Andoren would probably like to see this.", progress = "You're back! What have you found?", completion = "This is truly incredible. The hieroglyphs are undoubtedly titan, but the markings below it...\n\nSome of these characters resemble ancient Kaldorei writings. And you say the antechamber was covered in hieroglyphs?\n\nYou've made a find more monumental than any riches, {name}. Please, take whatever reward you prefer.", objectives = "Take the Grand Tablet to Andoren Dawnrise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25108] = { id = 25108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feegly the Exiled", description = "Saddest story I ever heard told, {name}. Feegly was one of our fastest diggers, until he got a hold of that - thing. \"The Tear of the Moons\" we called it. It changed him. Remade him. I wish it had stayed buried.\n\nFeegly was banished from Bael Modan but I've heard reports he's come sniffing around the dig site again. He's suffered enough, the wretched thing. If you find him down there, put ol' Feegly out of his misery.", completion = "<Marley nods grimly.>\n\nAye, it's for the best I suppose.", objectives = "Kill Feegly the Exiled in the Bael Modan Digsite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25109] = { id = 25109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gallywix Labor Mine", description = "We barely escaped with our hides intact!\n\nThe Trade Prince has a whole bunch of us enslaved and performing manual labor inside the cavern.\n\nGreely helped the seven of us to get out, but she was recaptured in the process.\n\n{name}, you're the only one crazy enough to walk into an exploding volcano! The assistant will be able to help you free the others.\n\nHurry! This place is about to blow for good!", completion = "<The assistant looks confused.>\n\nHuh... what? Who?", objectives = "Speak with Assistant Greely inside the Gallywix Labor Mine on the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25110] = { id = 25110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaja'Cola Gives You IDEAS! (TM)", description = "Assistant Greely is clearly bewildered and intimidated. How will she help you to find a way to rescue everyone in this condition?\n\nMaybe if she were to drink one of those Kaja'Cola Zero-One drinks you saw, she'd be able to have a bright idea?", progress = "Huh?", completion = "<Assistant Greely spots the Kaja'Cola Zero-One in your hand and her eyes seem to come to life.>", objectives = "Collect 1 Kaja'Cola Zero-One.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25111] = { id = 25111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scavengers Scavenged", description = "Now that I know you're not squeamish, I've got another job for you. Have you seen the red-feathered birds swarming around the bones out there? Those are fire rocs. They'll light you up good if you're not careful.\n\nThey're also pretty darn valuable thanks to their unique anatomy. Most of the hunters loafing around here aren't up to the task of killing fire-spitting buzzards for money... think you can handle it?", completion = "Alchemists pay through the nose for these things. Sure, maybe I tell some of them they're dragon parts, but that ain't my problem, right?", objectives = "Use Butcherbot to harvest 12 Fire Roc corpses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25112] = { id = 25112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Butcherbot", description = "I make my money around here selling animal parts. I've been perfecting a foolproof method of maximizing profit: The butcherbot!\n\nThese little guys are programmed to harvest every scrap of usable material from the wildlife around here, on a case-by-case basis. He does all the work, and best of all, only I know how to get the goods back out of him.\n\nIf you're interested in making some coin, take one of these guys for a spin. I need some glasshide basilisk parts; you'll find a bunch of them to the south.", completion = "Nice going, kid. Didn't lose any fingers? Good, we can get some more work for you then.", objectives = "Use the Butcherbot to harvest 10 Glasshide Basilisk corpses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25113] = { id = 25113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "corpid Poaching: Dunestalkers", description = "The bigger scorpids to the south, the dunestalkers, are too tough and dry for the tail meat to sell. But I'll tell you what everyone overlooks: the legs!\n\nI won't bother you with all the finer details of scorpid part appraisal, but suffice it to say they sell like hotcakes. Or crablegs. Crabcakes?\n\nAnyway, I don't care what the chefs do with them as long as the money flows. Bring me about, oh, twelve pounds of legs.", objectives = "Collect 12 Pounds of Dunestalker Legs from Scorpid Dunestalkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25114] = { id = 25114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "asilisk Poaching: Gazer Guts", description = "That last job didn't exactly paint you as the dainty type, so I think you're cut out for more.\n\nThe larger basilisks to the south, the gazers, get to some impressive sizes. The alchemists prefer the smaller brains, usually, but the other organs are better sized up.\n\nAt any rate, I'm no alchemist: I just know what Driz sells by the truckload. Bring us back a sack full of gazer guts.", objectives = "Collect 12 Gazer Guts from Glasshide Gazers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25115] = { id = 25115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blisterpaw Butchery", description = "The hyenas wandering the wastes here might look scrawny, but they've got some of the strongest jaws you'll find! If you're not careful, they'll take a leg off in one bite. That kind of bone strength is a valuable resource, my friend, just waiting to find a buyer!\n\nTake one of my Butcherbots with you. Jaw separation isn't an easy task, and this little guy has been set up to know exactly what to do. Just bring him back when he's full.", completion = "Beautiful! We'll have these puppies shined up and ready to sell in no time.", objectives = "Use the Butcherbot to harvest 10 Blisterpaw Hyena corpses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25116] = { id = 25116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "yena Poaching: Rabid Livers", description = "I know Driz hates sport hunting, but the way I see it, it's okay to have fun as long as you're not being wasteful! Right?\n\nWhat I mean is, the northern hyenas are no fun. The ones further south, they've all got nasty cases of rabies. Now that's fun, when a single deep bite could do you in! And what's more, the rabies makes the liver swell up so much, it's prized for its weight.\n\nNow I've gotten all worked up again. Could you bring back some livers while I sit here, bored? Sigh.", objectives = "Collect 12 Rabid Livers from Blisterpaw Hyenas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25117] = { id = 25117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scout's Dishonor", description = "The Dark Iron are up to their usual tricks out here. They've been keeping to themselves, but I just know trouble's brewing.\n\nWe're going to take a look at it. There's a Dark Iron Scout puttering around the center of what used to be the Loch, keeping an eye out. I want you to take him out and bring back any documents or orders he has.\n\nIf my suspicions are unfounded... I'll take the blame from Moira myself. Promise ya.", objectives = "Collect the Dark Iron Dispatch from the Dark Iron Scout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25118] = { id = 25118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking for Lurkers", description = "I don't know about you, but I'm not much a fan of spiders, much less the kind that come bigger than me. Loch Modan's a gorgeous place, but I'd say it could do without those horrid things waltzing around.\n\nTell you what, I've got some spare coin, and you look like a tough one. If you head out and off some of those things for me, I'll pay you for your time.", completion = "I'll rest easier knowing one of those lumbering things won't be wandering into my bedroom at night... again.  Thanks much.", objectives = "Kill 8 Forest Lurkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25119] = { id = 25119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impulse Hunting", description = "Ashlan's no doubt going to send you off to the Loch to investigate the Dark Iron hooligans he keeps muttering about. If you're headed down there, might as well make some coin while you're at it, right?\n\nThe loch's draining wiped out most of the wildlife in it. Not many places to swim anymore. But there's still crocolisks padding around on the now-dry ground.\n\nThey'll starve in time, so we may as well get 'em while they're fresh. Bring me back some full sides of croc and we'll talk rewards.", objectives = "Collect 6 Sides of Crocolisk from Loch Crocolisks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25120] = { id = 25120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marley's Final Flight", description = "Okay, {name}! Let's take these artifacts to my father and give him our report firsthand.\n\nThanks to your help my flying machine is ready to roll. We can fly there together and share in the glory.\n\nTalk to me when you're all set to move out!", completion = "<The battered dwarf hangs limply from the cockpit. As you approach the burning wreckage, his eyes flutter open.>\n\n<Marley Twinbraid is still alive!>", objectives = "Talk to Marley Twinbraid and take a spin in his flying machine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25121] = { id = 25121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Momentum", description = "It looks like we've got more work to do! Having Mr. Noggenfogger ask us to take care of the rest of the pirates is a true honor.\n\nSince you've been SO helpful, why don't you meet me at Lost Rigger Cove? I've just got to slip into something a bit more comfortable, so don't wait on me. I'll beat you there, promise!", completion = "Hi there! The fun's already started!", objectives = "Meet Kelsey Steelspark at Lost Rigger Cove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25122] = { id = 25122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morale Boost", description = "You've got to get all the Kaja'Cola Zero-One that you can and make the goblins drink it to boost their morale and free them!", progress = "Increase their morale, {name}, so that they will run to freedom!", completion = "I hate the Trade Prince, but you can't argue with the results of his methods. Kaja'Cola Zero-One is a huge improvement over regular old Kaja'Cola at half the calories and twice the ideas!", objectives = "Use Kaja'Cola Zero-One to free Ace, Izzy, Gobber, and 6 Goblin Survivors or Kezan Citizens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25123] = { id = 25123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Throw It On the Ground!", description = "This nightmare will never be over while Blastshadow the Brutemaster still breathes. There are a couple of problems though.\n\nOne, being a warlock, he's got a succubus named Delicia Whipsnaps. If you kill Blastshadow quickly, the demon will go back to where it was summoned from.\n\nThe second problem, since Blastshadow is a warlock, he has a soulstone that allows him to resurrect. You have to get his soulstone and destroy it so that he'll be dead forever!", progress = "The soulstone is the key, {name}!", completion = "Your soulstone has expired, Blastshadow!", objectives = "Destroy Blastshadow the Brutemaster's soulstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25124] = { id = 25124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brute Brutality", description = "I was thinking. You should probably take care of some of these Brute Overseers while you're doing everything else.\n\nYou know?", objectives = "Slay 6 Brute Overseers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25125] = { id = 25125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light at the End of the Tunnel", description = "Okay, we have got to get out of here before she blows for good!\n\nLet's head out the other end of the tunnel on the north side of the mine. We should be able to use one of the mine carts for a quick ride down the side of the volcano.", completion = "Looks a little rickety....", objectives = "Interact with the Mine Cart outside the Gallywix Labor Mine on the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25126] = { id = 25126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting Teeth", description = "The first order of business will be to put a little strength in your backbone. I could send you out to the Barrens to hunt kodo, but well, in all honesty, you're more useful to us alive than dead.\n\nI believe you'll be of more use to us slaughtering the boars you'll find in the farms to the north and northeast of here.", progress = "I hope you haven't returned to try and convince me that you have completed your task, {name}? No, of course not. I would think better of you.", completion = "Hmmm, not bad, {name}. But don't let it get to your head...you'll fight tougher than boars in your career.\n\nNonetheless, you've proven yourself well, and your next trial will be against a considerably more dangerous opponent, so you'll need some extra protection.", objectives = "Slaughter 6 Mottled Boars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25127] = { id = 25127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sting of the Scorpid", description = "I must send you back into the fields again, {class}. You will find large numbers of scorpids northwest of here. Bring me eight of their tails.\n\nThe antidote for their sting is actually made from venom extracted from their stingers. We keep large quantities of antidote for scorpid venom on hand to heal young bloods just like you...\n\nBut I'm sure you won't be needing any of that, will you?", progress = "The carapace of a scorpid isn't so thick that the strength of a determined warrior will be deterred. Strike strongly and without doubt, and the scorpids should prove easy prey.", completion = "There is an important lesson that you must take away from fighting scorpids. The smallest or largest of opponents can still send you to your doom. In fierce combat, any number of things can prove your downfall.\n\nI have no more to teach you, {name}. You have done well, and I will watch your progress with interest.", objectives = "Obtain 8 Scorpid Worker Tails.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25128] = { id = 25128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hana'zua", description = "Hey mon, take a knee and hear me out. We got a problem.\n\nA good friend of mine, Hana'zua, has gone out into the valley and he hasn't returned. Last I seen, he was headin' north, where the scorpids hunt. Maybe you go take a look for him? The spirits be tellin' me that he's not well.", completion = "<Hana'zua groans in pain.>", objectives = "Find Hana'zua in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25129] = { id = 25129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sarkoth", description = "{class}! I thought I would die out here with none to know of it. While I was hunting the scorpids of the Valley, I came across a particularly vicious-looking one. Hurling myself at it, I managed to inflict a massive blow to its claw before it closed around my leg.\n\nI wasn't ready for its stinger though, and it sliced down and into my chest, cutting into my flesh and letting my blood. Please, you must kill the scorpid for me! My honor must be upheld! I fought it up on the plateau to the south.", progress = "Ahhh... my father always said I would never amount to much, and here, lying beneath a tree as life seeps away, I'm afraid it looks like he was right.\n\nAt least I wish to die knowing that my last enemy in life lays dead.", completion = "My blow was not enough to kill him, but looking at the damage I inflicted gives me some small measure of pride. That small measure will be all I have to sustain myself if I die, and in that light, the short list of my life's accomplishments fills me with anger.", objectives = "Kill Sarkoth and bring his claw back to Hana'zua.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25130] = { id = 25130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Den", description = "Seeing the deed you have done for me steels my heart. I cannot fall so easily! I must endure!\n\nBut it remains that I cannot make the trek back to our settlement unassisted. Please, {name}, return and tell Gornek of my situation. Perhaps he can help me.", completion = "From your description of the beast, I believe you must be speaking of Sarkoth! It is no wonder that Hana'zua was overtaken by it. Aid will be dispatched to him immediately, trouble yourself no more with Hana'zua's plight.\n\nHowever, I must say, I am most impressed to hear that you brought Sarkoth to death. It is a feat to be proud of, {name}. And that you would fight for a stranger's honor, while other tasks occupied your time, your own honor is heightened.", objectives = "Bring the news of Hana'zua's plight to Gornek in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25131] = { id = 25131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile Familiars", description = "I trust the Valley of Trials will teach you much, young {class}.\n\nI was sent to the Valley to guide you, but I have discovered a growing taint here...\n\nOne of the Burning Blade - a foul, demon-worshipping cult - has made camp here in the Valley of Trials. He skulks in a cave to the north, and his vile familiars have spilled from its mouth to cause havoc.\n\nAs your first task against the Burning Blade, I bid you, defeat these familiars. Slay many and, if you survive, return to me.", progress = "To prove yourself against the Burning Blade, you must first defeat these vile familiars. Return to me when you have done this.", completion = "You have done well, {name}.\n\nAlthough the Vile Familiars were merely pets of the darker powers within the Burning Blade, your success against them foretells greater deeds ahead.", objectives = "Kill 8 Vile Familiars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25132] = { id = 25132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Blade Medallion", description = "Through my divinations, I see that an item of power--a medallion--hides deep within the Burning Blade Coven, guarded by beasts and black magic. We must have it.\n\nFor too long these demon-worshippers have defiled our homelands. Cleanse the coven of its demonic taint by slaying the fel beasts and their leader. Return with this medallion as proof of your deed.\n\nGo, {name}. You will find the coven in a cave to the north.", progress = "Is your task complete, {name}?", completion = "You retrieved it!  Well done!\n\nYour efforts within the Burning Blade Coven are key in rooting out this cult in the Valley of Trials.  But I fear they have further aims in our land.\n\nWe have not seen the end of them.", objectives = "Slay 5 Felstalkers and obtain the Burning Blade Medallion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25133] = { id = 25133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Sen'jin Village", description = "Your trials against the Burning Blade are finished... here in the Valley. But I want you to report your findings.\n\nGo to the troll village of Sen'jin and seek out Master Gadrin. Sen'jin Village is east out of the valley, then right at the fork.\n\nTell Gadrin of the Burning Blade, and that they have reached the Valley of Trials. Discover from him if they have yet reached Sen'jin.\n\nGo, {name}, and be swift. I fear the evil found in the Burning Blade Coven is but the herald of a larger threat...", completion = "Hm... your report comes at a bad time.  The Burning Blade is no longer seen here in Sen'jin, but we will be vigilant in our efforts to prevent their return to the area.\n\nThe orcs are friends of the Darkspear Trolls.  Honorable friends.  We want to help the orcs, but... we need help too.", objectives = "Speak with Master Gadrin in Sen'jin Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25134] = { id = 25134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lazy Peons", description = "Cursed peons!  They work hard gathering lumber from the trees of the valley, but they're always taking naps!  I need someone to help keep the peons in line.\n\nYou look like the right {race} for my task.  Here, you take this blackjack and use it on any lazy peons you find sleeping on the job.  A good smack will get them right back to work!  Return the blackjack when you're done.\n\nLook for them underneath the trees in the valley.  Lousy slacking peons...", progress = "No good lazy...\n\n Eh?  Do you have my blackjack?  Did you catch any peons sleeping on the job?!", completion = "Good, good.  Maybe they'll think twice before slacking next time!  Thanks for the help!", objectives = "Use the Foreman's Blackjack on 4 Lazy Peons when they're sleeping.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25135] = { id = 25135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thazz'ril's Pick", description = "{name}, you are a dependable {race}. Can I count on you for another task?\n\nSome time ago I was surveying the cave to the north for minerals, and I left my favorite pick behind. When I later returned to retrieve it I found the cave was filled with vicious beasts! Will you go into the cave, the Burning Blade Coven, and get my pick?\n\nI left it in a chamber with waterfalls. My pick has a spell on it so you can see it in the dark, so you won't have to worry about finding it... just what's guarding it!", progress = "Have you entered the Burning Blade Coven, {name}?  Did you find my pick?", completion = "Great, you got it!  Thanks a lot, {name}.  This is my favorite pick!  Now if my peons ever finish chopping down these trees, maybe we can find a nice cave to mine!", objectives = "Bring Thazz'ril's Pick to Foreman Thazz'ril.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25136] = { id = 25136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galgar's Cactus Apple Surprise", description = "It sure gets hot out here in the Valley of Trials.\n\n<Galgar wipes his brow.>\n\nIf only I had some cactus apples, I could make my famous cactus apple surprise! Nothing cools you off faster than a piece of that delicious treat.\n\nI'll tell you what, {name}. If you bring me six cactus apples, I'll make you a few portions of cactus apple surprise to take with you on your adventures. If you're interested, you can find cactus apples growing near the cactus plants around here.", progress = "Have you finished collecting cactus apples?", completion = "Wonderful, {name}! As promised, here is your cactus apple surprise plus a little something extra.", objectives = "Obtain 6 Cactus Apples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25137] = { id = 25137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valley of Trials: PRK - H - Warlock Pet Imp", description = "Those warlocks who came before us have earned the distrust of the Horde, and while we are tolerated, we are not loved.\n\nThis has not brought the warlocks closer together, however, as many choose to live reclusively, dabbling in their magics alone. I will not seek to lead you down one path or the other, but only help you in your maturation.\n\nBefore I teach you the art of summoning, bring me six heads of the vile familiars from the cave to the northeast.You will learn:", objectives = "Bring 6 Vile Familiar Heads to Ruzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25138] = { id = 25138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphic Parchment", description = "Ah, while you were gone a parchment came for you, {name}.\n\nRead it when you have time. If I'm not mistaken, it came from the mage trainer Acrypha. She would have words with you when you're ready.", progress = "What?  Who are you?  Get away!\n\nOh, you're the other {class}, the new one, the one with the big arms.  Come on, let's get to work.", completion = "Ahh, where to start... introductions!  I'm Acrypha - the one who sent you that parchment - I've spent the last several years in an Undercity library, my head in a book.  I learned everything I could about the arcane, and now I've returned home to share it with grunts like yourself.\n\nShall we begin?", objectives = "Read the Glyphic Parchment and speak with Acrypha in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25139] = { id = 25139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steady Shot", description = "You already know how to fire an arcane shot. Good. But doing so depletes your focus. To gain your focus back you will need to switch to a second type of ranged attack.\n\nGo out and get some more experience. As you do, you'll learn some new abilities. The first of these will help you get your focus back.", completion = "You learn quickly.", objectives = "Reach level 3 to learn Steady Shot. Locate a Training Dummy and practice using Steady Shot 5 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25140] = { id = 25140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swine Hunting", description = "Just to the south of this village, you will find a young swine that goes by the name of Lo'shall.  He hides among the cactus and the trees.  While he is small of size, he conceals an intelligence that most boars lack.\n\nFind him, pluck one of his hairs, and then return to me.\n\nRemember what I taught you, {name}.  You may find Track Beasts to be helpful here.", objectives = "Pluck Lo'shall's hair. You may wish to use Track Beasts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25141] = { id = 25141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eviscerate", description = "Let's start with the basics, shall we?  I'm the only rogue trainer in town, so you're going to have to learn it from me.\n\nGo get some more experience, figure out how to eviscerate your foes, and then show me on the training dummies here. I'll evaluate your form.", completion = "You won't be sorry.  The ability to capitalize on the opportunities created by previous attacks is one of our greatest strengths.", objectives = "Reach Level 3 to Learn Eviscerate, then locate a Training Dummy and practice using Eviscerate 3 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25142] = { id = 25142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Shadows", description = "I want to see you try to sneak past me.  I'll still be able to detect you, since you're still a novice, so don't try anything funny.  I just want to see what you've learned.", objectives = "Use your Stealth ability next to Rwag in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25143] = { id = 25143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Strike", description = "As you grow in power by gaining levels, you will discover the power to use new abilities. The first you will discover on your journey is Primal Strike.\n\nUse it to deliver a strike with your weapon, infused with the power of the elements.\n\nIt is time to learn and master your new skill. Practice using it on the training dummies outside the Den.", completion = "Very well.  Now that you know how to speak with the elements, we will test your bond with them.", objectives = "Learn Primal Strike by reaching Level 3, then look for a training dummy near Shikrik and practice using Primal Strike 3 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25144] = { id = 25144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rock Meets Flesh", description = "Our village leaders have apprehended human invaders that have attempted to enter the valley.  These invaders are kept in cages, in the cave to the west.\n\nI want you to use this ability on one of these invaders, {name}.  Enchant your blade with the power of earth, then strike out at these enemies!", objectives = "Defeat a Captured Northwatch Scout while your weapon is enchanted with Rockbiter Weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25145] = { id = 25145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption", description = "It is my duty to train you, and I intend to do just that.\n\nAs you become more powerful, you will begin to hear the fel voices revealing new spells to you.\n\nGo, get more experience, learn a new spell, and then practice your new spell against one of the training dummies around here.", completion = "You appear to be a quick learner.", objectives = "Reach level 3 to learn Corruption. Locate a Training Dummy and practice casting Corruption 5 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25146] = { id = 25146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Demonic Fire", description = "Our village leaders have apprehended human invaders that have attempted to enter the valley.  These invaders are kept in cages, in the cave to the west.\n\nI want you to burn one of these invaders, {name}.  Cast your newly-learned spell on the human dogs, then watch them suffer.", objectives = "Cast Immolate on a Captured Northwatch Scout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25147] = { id = 25147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charge", description = "I've been instructed to prepare you for battle. Though, from the look of you, it looks like you've already spent a little time out in the field. Good.\n\nAs you continue your journey, you'll discover that you can begin to use new techniques\n\nGo, get some more experience, and teach yourself how to Charge, then show me what you've learned.", completion = "You understand now?  Good, let's try it out.", objectives = "Reach level 3 to learn Charge. Locate a Training Dummy and practice using Charge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25148] = { id = 25148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hone Your Holler", description = "Our village leaders have apprehended human invaders that have attempted to enter the valley.  These invaders are kept in cages, in the cave to the west.\n\nI want you to use your shout on one of these invaders, {name}.  Defeat a captured Northwatch scout while under the effects of your battle shout.  Return when you are successful.", objectives = "Defeat a Captured Northwatch Scout while under the effects of Battle Shout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25149] = { id = 25149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost Nova", description = "Alright, here's the easy part.\n\nAll you have to do to deepen your connection to the arcane is to get more experience and grow your power. You'll begin to find that you can cast new spells.\n\nYou'll see. Go try it, and show me what you learn.", completion = "Good.  Now we practice.", objectives = "Reach level 3 to learn Frost Nova. Locate a Training Dummy and practice using Frost Nova 2 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25150] = { id = 25150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empowered Minds", description = "Arcane Intellect is a spell that you can use on yourself, your friends, or even random passers-by.  While under the spell's temporary effect, you should feel a bit more... mentally acute.  Now let's try it out.\n\nI want you to cast Arcane Intellect on someone.  Actually, scratch that.  I want you to cast it on ME.", objectives = "Cast Arcane Intellect on Acrypha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25151] = { id = 25151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Needs Ale!", description = "<Marley grasps the side of your head with a shaking, bloody hand.>\n\nAle... Must... have ale...\n\nOl' Barkerstout from inside. <He coughs.> That should ... do the trick.", progress = "<Marley's breathing is ragged, coming and going in shuddering gasps.>\n\n<His eyes look at you imploringly.>", completion = "<Marley's eyes sparkle as you rush toward him with the ale. He grasps the mug in both of his shaking hands and upends it, white foam spilling out over his blood-caked beard.>\n\nAh... that's the stuff. Ol' Barkerstout... Thank you, friend.\n\nThat'll make this... a little easier.\n\n<Coughing one final time, he slumps over the shattered control console, the half-empty mug crashing to the ground and spilling its contents into the sand. His eyes glaze over.>\n\n<Marley Twinbraid is dead.>", objectives = "Search Bael'dun Keep for a Mug of Ol' Barkerstout and bring it to Marley Twinbraid at the entrance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25152] = { id = 25152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Place In The World", description = "Finally, you are of age, {name}... of age to battle in the name of the Horde. To conquer for the glory of the Warchief.\n\nYes...\n\n<Kaltunk looks you over.>\n\nYou will do nicely.\n\nNo doubt you wish to find a great dragon or demon and strangle it with your bare hands, but perhaps it would be wise to start on something less... dangerous.\n\n<Kaltunk laughs.>\n\nReport to Gornek, he should be able to assign a task better suited to a young {class}. You will find him seated at the fire behind me.", completion = "Another one of Kaltunk's recruits, hm?\n\nA sorry state of affairs we find ourselves in if this is the best the Horde can produce. No matter. By the time we think you're ready to leave the Valley, you'll be a proud warrior of the Horde.", objectives = "Speak with Gornek.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25153] = { id = 25153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bael'dun Rescue", description = "Help - Help! You've got to do something!\n\nSome dwarves are still inside - so many - they're trapped in the debris. Buried alive. The flames! It's a nightmare in there. We don't know how much longer until the roof collapses...\n\nPlease, {class}, you've got to save them!\n\nRun inside. Use the emergency fire valves to protect yourself from the flames. You're the only hope they have...", progress = "So many corpses... I don't know how I got out alive...", completion = "You're a legend, {name}.\n\nThe other survivors and I will be telling the story of your deeds for years to come.", objectives = "Go into Bael'dun Keep and rescue 10 Bael'dun Survivors from the rubble.\n\nUse the Emergency Fire Valves to protect yourself from the flames.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25154] = { id = 25154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Present for Lila", description = "I'm trying to impress this trade ship captain Lila.  I've been working on a necklace to match her lovely purple hair, but the gems have gone missing!  They were there when I was showing them off to my good friend Curver last evening.  We were drinking moonshine and I blacked out - when I woke up the gems were gone!  They must have been darn good thieves, because Curver didn't see anything.\n\nHer ship is coming in tonight, and I really need three nightstones to get her present done.  Help me out here!", progress = "Have you brought me the nightstones?", completion = "Thanks!  I'm sure to beat out that Marith Lazuria in Orgrimmar with these!  I can't wait to see the look in her beautiful eye when I give this to her.", objectives = "Cut three Timeless Nightstones and give them to Isabel Jones in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25155] = { id = 25155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogrezonians in the Mood", description = "I was supposed to receive a shipment of jasper from Azeroth Express, but I just heard their ship crashed into some tiny island called Ogrezonia.  I worry about the crew, as the giant female ogres on the island are rumored to perform horrible rituals on men who happen upon their island.  My work must go on, though, and we need those gems.  I've heard great things about your skill as a jewelcrafter - could you deliver three jagged jaspers by the end of the day?", progress = "Have you brought me the gems I need?", completion = "Your work is as good as it is rumored to be!", objectives = "Cut three Jagged Jaspers and give them to Isabel Jones in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25156] = { id = 25156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Goo", description = "Instead of using the tired old method of setting gems into rings and such, I use an innovative new method.  I simply glue on the gems with Barnsworth Elemental Glue!  The professor needs more elemental goo for another batch, though, and I have a whole bunch of setting to do.  Can you go get me some?", progress = "Did you bring me the elemental goo?", completion = "Thanks.  Erm.  Just set them over there.  I need to figure out how to get my hand off of this jar�", objectives = "Collect 10 Elemental Goo from any Cataclysm elemental and bring them to Isabel Jones in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25157] = { id = 25157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Latest Fashion!", description = "Professor Barnsworth has been working on this new stardust - what with the fashion in Stormwind this season being about all things sparkly, I'm sure if we can get it to the market it will be all the rage!  The Jewelcrafter's Association, however, won't let us market it until we've completed some humanoid testing - something about tinkering with magical dust being dangerous or some such nonsense.  Well, I suppose we need to humor them.  Take this bag and test out Stardust No. 2 on some humanoid subjects.", completion = "It did what!?  We're ruined!  Hmm.  Well, actually... Maybe the professor can find some other applications for it?", objectives = "Test Stardust No. 2 on 10 \"humanoid subjects\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25158] = { id = 25158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nibbler! No!", description = "Lila's pet Nibbler got into my workshop again!\n\nI was making a bracelet, to be delivered today.  The work was almost done, except for the gems.  I spent all night cutting them, but when I stepped out for a bit of breakfast, the little beast came into my workshop and swallowed every gem in sight!  The thing can digest ANYTHING, and trust me, you'd break your back trying to pick up its leavings.\n\nI need to get replacement gems fast; the courier is coming in tonight.  Help!", progress = "Have you brought me those solid zephyrites I need?", completion = "You've really saved my skin, {name}.  Thanks!", objectives = "Cut three Solid Zephyrites and give them to Marith Lazuria in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25159] = { id = 25159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Latest Fashion!", description = "Dr. Vernstrom has been working on this new stardust - what with the fashion in Orgrimmar this season being about all things sparkly, I'm sure if we can get it to the market it will be all the rage!  The Jewelcrafter's Association, however, won't let us market it until we've completed some \"live testing\" - something about tinkering with magical dust being dangerous or some such nonsense.  Well, I suppose we need to humor them.  Take this bag and test out Stardust No. 2 on humanoid subjects.", completion = "It did what!?  We're ruined!  Hmm.  Well, actually...  Maybe the doctor can find some other applications for it?", objectives = "Test Stardust No. 2 on 10 \"humanoid subjects\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25160] = { id = 25160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Present for Lila", description = "I'm trying to impress this trade ship captain Lila.  I've been working on a necklace to match her lovely purple hair, but the gems have gone missing!  They were there when I was showing them off to my good friend Bonder last evening.  We were drinking moonshine and I blacked out - when I woke up the gems were gone!  They must have been darn good thieves, because Bonder didn't see anything.\n\nHer ship is coming in tonight, and I really need three nightstones to get her present done.  Help me out here!", progress = "Have you brought me the nightstones?", completion = "Thanks!  I'm sure to beat out that Isabela Jones in Stormwind with these!  I can't wait to see the look in her beautiful eye when I give this to her.", objectives = "Cut three Timeless Nightstones and give them to Marith Lazuria in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25161] = { id = 25161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogrezonians in the Mood", description = "I was supposed to receive a shipment of jasper from Azeroth Express, but I just heard their ship crashed into some tiny island called Ogrezonia.  I worry about the crew, as the giant female ogres on the island are rumored to perform horrible rituals on men who happen upon their island.  My work must go on, though, and we need those gems.  I've heard great things about your skill as a jewelcrafter - could you deliver three jagged jaspers by the end of the day?", progress = "Have you brought me the gems I need?", completion = "Your work is as good as it is rumored to be!", objectives = "Cut three Jagged Jaspers and give them to Marith Lazuria in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25162] = { id = 25162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Goo", description = "Instead of using the tired old method of setting gems into rings and such, I use an innovative new method.  I simply glue on the gems with Vernstrom Elemental Glue!  The doctor needs more elemental goo for another batch, though, and I have a whole bunch of setting to do.  Can you go get me some?", progress = "Did you bring me the elemental goo?", completion = "Thanks.  Erm.  Just set them over there.  I need to figure out how to get my hand off of this jar�", objectives = "Collect 10 Elemental Goo from any Cataclysm elemental and bring them to Marith Lazuria in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25163] = { id = 25163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Did This?", description = "Sabotage! It had to be. The whole fortress magazine exploded. The Horde must've gotten someone inside...\n\n{class}, if you've the stones to rush into that burning nightmare... look for some clues as to who did this to us. The General will want to know! Look for a Horde corpse in the wreckage and get to the bottom of this disaster...", completion = "<One smoldering corpse stands out amidst the carnage. The dead goblin clutches the schematics of the fortress in his lifeless hand...>\n\n<The Bilgewater Cartel goblins. They did this!>", objectives = "Look for a Horde corpse within Bael'dun Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25164] = { id = 25164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Backed Into a Corner", description = "The naga are upon us, {class}. Aid us in fightin' dem off!", progress = "Dey seem relentless, but we gonna turn dem back!", completion = "I'm glad you were here, mon.\n\nToshe be lookin' like he wants to chase dem down. You should go help'em.", objectives = "Defend the Earthen Ring camp until the naga retreat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25165] = { id = 25165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Trust a Big Barb and a Smile", description = "Next, we gonna get some poison from the scorpions that be runnin' around here.  But don't you worry, Bom'bay's not gonna let you get hurt!\n\nBom'bay's got a big totem that you gonna stick in the ground when the scorpion strikes.  The totem gonna suck up all the poison, and you gonna walk away still breathing.  Sound good?", progress = "You got the jujus, ya?", completion = "This is it!  The scorpid juju Bom'bay been waitin' for!  Now we gonna fix you right up, {class}.\n\nYou come back to Bom'bay when you be needin' a pickup.  Bom'bay got the spells to fix ya!", objectives = "Obtain 6 samples of Scorpid Venom by placing the Poison Extraction Totem near a Clattering Scorpid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25166] = { id = 25166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Dreadbeard", description = "This is getting pretty fun, but let's not forget we're here for Gnomeregan!\n\nWe spotted the captain of the Southsea over on one of his boats to the south, past where all the fighting is. He's all alone on his little boat, undefended!\n\nIf you go take care of him, we'll have the rest of these pirates mopped up in no time.", progress = "My patience is beginning to wear thin. I don't have enough time to wait around for you, so kill that captain already.\n\nUm, I mean, please? Tee-hee?", completion = "He was controlling a sea giant? Fascinating. If we'd managed to investigate further...\n\nOh, I mean, wow, that's totally crazy! But thank goodness he's gone, hooray! Mister Noggenfogger will be so pleased.\n\nHere's a nice big reward, you!", objectives = "Kill Captain Dreadbeard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25167] = { id = 25167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Chain", description = "Aw man, this ain't good.  Not one bit, mon.\n\nThrall's off to sea, Vol'jin's taking care of business in Echo Isles, and old Master Gadrin is left behind to take care of Sen'jin.  And then what happens?  Those humans come outta Northwatch Hold and set up camp in our backyard!\n\nLucky for us, they just got here, and they're still setting up their base.  You can help out old Gadrin by destroying those big supply crates they carry, and by killing the laborers carryin' them. You'll find'm to the southwest.", progress = "We gotta get rid of these humans, {class}.", completion = "Well, we've stymied their efforts for now, but they're still here.  We'll have to press on, {name}.", objectives = "Destroy 3 Northwatch Supply Crates and kill 10 Northwatch Lugs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25168] = { id = 25168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purge the Valley", description = "Northwatch is a highly-defended stronghold southwest of here, across the harbor.  It's a strategically-located stronghold that the Horde still struggles to overtake.  We don't need the humans setting up another Northwatch here in Durotar.\n\nSweep through the valley to the west and slay these humans, {name}.  Let them know the power and the fury of Sen'jin.", completion = "A battle well-fought, {class}, but I still have my doubts about our effectiveness.  These humans don't seem to be going anywhere.\n\nYou, however, have done more than could reasonably be asked of any loyal member of the Horde.  Thank you.", objectives = "Defeat 12 Northwatch troops in Northwatch Foothold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25169] = { id = 25169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The War of Northwatch Aggression", description = "These humans in the west, they don't just wanna camp out in Durotar, mon.  They got bigger plans, and those plans involve takin' our home and leavin' our skulls on pikes.\n\nWell I'm not havin' it.  Nope!  Not Lar!  I've got family here in Sen'jin, and I'll be damned if I let one of those brutes put my Tai'tasi's head on a stick!\n\nThey've got their plans written down in there, mon.  Big scrolls, real important-lookin'.  We gonna burn those scrolls before they burn us.", progress = "Destroy those humans, {name}.", completion = "Good work, hero.  You done good for Sen'jin today.  No... you done good for all of Durotar.", objectives = "Destroy the 3 sets of Attack Plans held within Northwatch Foothold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25170] = { id = 25170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning Up the Coastline", description = "Heya mon!  Bom'bay be workin' on some new mojo.  You wanna try a piece of it?  Well, before ya do, Bom'bay's gonna need ya to pick up some jujus.\n\nFirst, Bom'bay needs ya to get some o' the goop from the crabs down by the water.  Let me see your hands!\n\n<Bom'bay examines your hands closely.>\n\nBom'bay gonna need 5 handfuls.  Go on now!", progress = "You bring the jujus, I show you my mojo.", completion = "Ya mon, that's tha stuff.  Now we get the other jujus.", objectives = "Obtain 5 handfuls of Crawler Mucus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25171] = { id = 25171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riding On", description = "We gotta pass the word on to Razor Hill.  These humans may be defeated today, but tomorrow they'll come again, and when they do, we'll need help from the orcs.\n\nSpeak with Jhash, outside the gates of Sen'jin.  He'll give you a ride to Razor Hill.  His wolves know the path well.", completion = "That {race} wants us to send help?  Bah, he can forget it.  I've got my own human problems to worry about, and even those are the least of my worries right now.\n\nSen'jin Village is right next to Echo Isles and the Valley of Trials.  Old Gadrin should find plenty of youngbloods to help him with his human infestation.", objectives = "Speak to Raider Jhash to get a ride to Razor Hill. Once there, speak with Gar'thok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25172] = { id = 25172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invaders in Our Home", description = "You're not just another grunt - you seem to be a serious {class}. Good, because that's exactly what I need.\n\nTry not to let the word out, since I don't want to cause a panic... but there have been reports of more humans nearby. This is an egregious betrayal of the peace that we negotiated with that miserable Jaina Proudmoore! We can't allow humans here in Durotar, and especially not here in the Valley.\n\nYou will find them to the south. Slay them quickly, before their numbers increase any more.", progress = "Quickly, {name}. Dispatch of these humans in our valley.", completion = "Executed with quickness and discretion.  A job well done.", objectives = "Slay 7 Northwatch Scouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25173] = { id = 25173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Bad to Worse", description = "Tiragarde Keep lies to the southeast of here, on Durotar's eastern shore.  You probably passed it on your trip from Sen'jin Village.  This castle has been a thorn in my side for too long.\n\nHumans from Kul Tiras lived in the castle for years, thwarting my every attempt to crush them.  When the cataclysm hit us, the shore was wiped out, along with the castle and all the humans.  However, these upstarts from Northwatch have moved in to take their place!\n\n<Gar'Thok roars in aggravation.>", completion = "Word of your bravery travels fast, {class}. Tales of your victory at Tiragarde Keep will be heralded in Orgrimmar.", objectives = "Kill 6 Northwatch Marines, 6 Northwatch Sharpshooters, and Lieutenant Palliter in Tiragarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25174] = { id = 25174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twinbraid Needs to Know", description = "<General Twinbraid will want to know the details of this cowardly attack. You gather up the evidence.>", completion = "What... WHAT!?\n\nBael'dun in ruins? Corpses everywhere - no. No!\n\n<You describe the evidence you found at the scene.>\n\nThe Bilgewater goblins, was it? They want a fight do they? We'll show 'em what it means to be a part of the Horde, we will. I'll fill the Battlescar with their corpses. I'll redden the dirt with their blood.\n\n<Twinbraid grabs you by the collar.>\n\nGoblins. Are going. To die!", objectives = "Report to General Twinbraid at Twinbraid's Patrol in Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25175] = { id = 25175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bad News", description = "<You gently close Marley's eyes.>\n\n<Someone is going to have to tell General Twinbraid that the Horde has killed his only son.>\n\n<That someone is you.>", completion = "<General Twinbraid hurls his axeblade into the dirt, his voice quiet but his body quivering with disbelief and rage.>\n\nThat was my boy, {name}. My only boy.\n\nThey've made it personal, {class}. Personal.", objectives = "Bring the bad news to General Twinbraid at Twinbraid's Patrol in Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25176] = { id = 25176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exploiting the Situation", description = "<Hey there, handsome!  I've had my eye on those big, beefy biceps ever since you stepped into town./What're you looking at> ugly?  I've seen you walking around Razor Hill, trying to steal MY men from me!;\n\nListen, I've got something for you to do.  I hear Gar'Thok's got you headed over to Tiragarde.  While you're there, think you could find some abandoned Kul Tiras knicknacks?\n\n<Thanks sweetie!/Don't ask why> just get to it!;", progress = "<Gail purrs disarmingly at you.>", completion = "You brought me my treasure!  What a sweetheart!", objectives = "Obtain 6 pieces of Kul Tiras Treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25177] = { id = 25177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storming the Beaches", description = "Now that those humans are out of our hair for a bit, we can move on to more pressing matters.\n\nThe cataclysm utterly decimated Durotar's eastern coast.  You saw the wreckage that it made of Tiragarde.  The devastation was even worse on the coast to the east of here.\n\nAfter the first wave, the beach was overtaken by angry elementals that came from the sea.  I sent grunts to take care of it, but the onslaught was too much.  I'm guessing you'll have a little more luck than they did.\n\nBeware the tides!", completion = "The scent of the sea hangs about you, {name}.  Your efforts may have purchased another day for Razor Hill.\n\nI will pass word of your deeds up my chain of command.  You have our gratitude.", objectives = "Kill 11 Foaming Sea Elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25178] = { id = 25178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipwreck Searching", description = "<Hey handsome, welcome back!  You wouldn't mind running another errand, would you?  I'd be EVER so grateful.../You!  Stop right there> you tramp!  I'm not finished with you yet.;\n\nI hear you're headed off to the shore east of here.  The beach is filled with crashed ships, and those ships have gnomish tools in them... tools that I can use.\n\n<See you soon, beefcake!/Get cracking> missy!;", progress = "Has my knight in shining armor returned?", completion = "You really know how to treat a girl, you know that?  If you ever need anything...", objectives = "Obtain 4 sets of Gnomish Tools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25179] = { id = 25179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loss Reduction", description = "You've got to help us.  The elementals... they're stronger than they look, and they come in waves.  They took us completely by surprise, and we were overcome.\n\nMany of my fellow grunts lay dying on the beach.  If you could save them... I would be grateful, as would Gar'Thok back in Razor Hill.", completion = "I've already spoken with several orcs that have returned from the beach.  All of them told me that you were the one who saved them.\n\nYou've done a noble task today, {name}.  Lok'tar ogar!  For the Horde!", objectives = "Rescue 4 Injured Razor Hill Grunts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25180] = { id = 25180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tablets of the Earth", description = "Some time ago, Brann sent King Magni an urgent message from Ulduar. He said he'd found an ancient titan cache with mysterious and important relics. King Wrynn dispatched one of his fastest ships to Northrend to transport the courier. I was to meet him here and examine the tablets, but the courier is nowhere to be seen.\n\nMagni is worried, {name}. I haven't heard anything about the courier's arrival. Would you be willing to travel to Stormwind Harbor and see if he's arrived?", progress = "Did you meet up with the courier?", completion = "Why would Twilight's Hammer take an interest in these tablets? Brann himself wrote that he hardly knows their significance, although he did mention something about becoming one with the earth. I will need to confer with my fellow Explorer's League scholars to decipher these as soon as possible.\n\nThank you, {name}. Without your aid, these tablets would've fallen into enemy hands.", objectives = "Bring the Tablets of Earth to Advisor Belgrum in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25181] = { id = 25181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tablets of Fire", description = "I'm expecting the arrival of a courier traveling from Northrend. He's carrying a collection of ancient titan treasures, ones I'm hoping will shed light on my troubling visions. The shaman should've arrived on one of the recent zeppelin flights and I'm starting to get worried.\n\nHe was to meet me by the zeppelin tower southwest of Orgrimmar's gates, but I don't want to miss my audience with the warchief. Would you be willing to look for the courier and see what's delaying him?", progress = "Did you meet up with the courier?", completion = "Why would Twilight's Hammer take an interest in these tablets? Their contents are a mystery to our most learned scholars and deciphering them will take some time. If Twilight's Hammer knows about these relics and desires them, what more are they plotting?\n\nWe are most fortunate that you protected them from capture, {name}.", objectives = "Bring the Tablets of Fire to Earthmender Norsala in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25182] = { id = 25182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill 'em All!", description = "I want to see some dead goblins, {name}! Just west of here you'll find a whole warren of those little insects burrowing into the mountain.\n\nLet's see to it that they're digging their grave.\n\nDestroy them. Lay waste to their whole grubby operation. They've sown their own demise in Bael'dun, {class}, and it is time to meet the reaper.", completion = "Dead? Good.\n\nLet word of this deed spread, and with it, terror.\n\nThe Horde will feel the consequences of their attack on Bael'dun, and they'll rue the day they ever crossed us, {name}.", objectives = "Kill 10 Frazzlecraz Miners at the Frazzlecraz Motherlode in Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25183] = { id = 25183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...And Bury the Rest", description = "It's not enough to kill 'em - after Bael'dun, I want to give those goblins a taste of their own.\n\nGo into Frazzlecraz's mine and arm a pile of the explosives inside.\n\nAt the entrance to the mine you should see some sort of switch or plunger. Once the explosives are armed, use the plunger to blow that place sky-high. Put the fear in 'em, {class}!", progress = "<The plunger has a number of jury-rigged wires leading into the mine.>", completion = "<The explosives are armed and ready!>", objectives = "Arm 6 Frazzlecraz Explosives in the Frazzlecraz Motherlode mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25184] = { id = 25184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Mine Cart Ride", description = "All you have to do is jump in and speak with Assistant Greely when you get to the bottom.", completion = "As we would say in the Tinker's Union, out of the heat-applied metallic cooking container and into the oxydizing, energetic mixture of reacting gases and solids!", objectives = "Use the Mine Cart to take a ride to the end of the line and then speak with Assistant Greely.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25185] = { id = 25185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deed Is Done", description = "<You shield your eyes from the blast and the debris as the mine implodes onto itself.>\n\n<General Twinbraid will be pleased, but somehow you doubt it'll be enough to quench his thirst for vengeance.>", completion = "<Twinbraid nods as you describe the destruction of the mine, but his eyes still burn with rage.>\n\nVery nice work, {name}. I suppose there's some strategic value in depriving the Horde of those minerals, but I'd have done it anyway just to crush those little green monstrosities.", objectives = "Return to General Twinbraid at Twinbraid's Patrol in Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25186] = { id = 25186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Futile Resistance", description = "{name}, I certainly don't want to deliver my report to Commander Singleton without at least a little bit of good news. We've got to wrestle control of these roads back from these Horde holdouts.\n\nFrom what we can gather, Kona Thunderwalk is the name of the ringleader. He's got a camp just north of here. A Stonetalon native, he knows these roads better than his own hide. If we can wipe him out, resistance from the west might vanish.\n\nFind and kill Kona Thunderwalk, then report to Commander Singleton!", completion = "So our supplies aren't getting through? Hmmm. Honor's Stand just gets more and more isolated.\n\nStill, the defeat of Thunderwalk should send a signal to our foes that we mean to stay. Thank you, {name}.", objectives = "Slay Kona Thunderwalk on the border between Stonetalon and Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25187] = { id = 25187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in the Floods", description = "The recent cataclysmic events have done more than wash a few boats onto our shore, {class}.  The Southfury River has overflowed, and Durotar's entire western basin is now flooded.\n\nThere are still people out there.  I've been searching for a while, but haven't been able to find anything.  Would you mind using my telescope and taking a look for yourself?", progress = "What have you seen?", completion = "I see... so the trick is that you need to put the LITTLE end of the spyglass up to your eye.  I'll remember that piece of information.", objectives = "Use Thonk's Spyglass to search for survivors in Southfury Watershed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25188] = { id = 25188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watershed Patrol", description = "My post is here on the tower, {name}, and I cannot leave it.  I need someone to go out there and help the people who are still trapped in the river's overflow.\n\nCan I count on you?", completion = "I used that trick you taught me with the spyglass, and I watched you running around down there.  Quite impressive!\n\nHow'd you make the old woman fly, by the way?", objectives = "Search the Southfury Watershed and help the people you saw in the spyglass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25189] = { id = 25189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits Be Praised", description = "Who are you?  What happened?\n\nI was alone in my hut, meditating, when...\n\nAhh, I remember now.  The spirits cried out, and the river swept in.  I'm lucky that you found me here.  I am old, and no longer physically able to endure the elements like this.  Will you lead me out of here?", completion = "My grandmother was a powerful shaman in her day.  I thought she had lost most of her powers in her old age, but I suppose some things stay with you forever.", objectives = "Escort Grandmatron Tekla to Raggaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25190] = { id = 25190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raggaran's Rage", description = "The quilboar are a stain on the land that not even the river can wash away.  They told me to evacuate, but I told them that my job was not yet done.\n\nHrrrraaagh!  I hate quilboar so much!  Will you help me kill them?", progress = "I hate quilboar!", completion = "<Raggaran appears to have calmed down a bit since your last encounter.>\n\nGood, good.  One step closer to eliminating those beady-eyed, basket-wearing, hog-nosed, two-toed...\n\n<Raggaran's anger is clearly rising again.>\n\n...hunchbacked, squealing, prickly... no-good... gnome-loving... GREEEAAAAGH!  Quilboar!", objectives = "Kill 4 Razormane Quilboar and 4 Razormane Scouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25191] = { id = 25191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survey the Destruction", description = "I had heard of enormous seismic anomalies here in Kalimdor, but I had no inkling that the geological chaos would be so profound!\n\nI need an up-to-date survey of the destruction while I stay here to study the seismographic readings. Could you gather some data via my automated survey craft? I'll take care of all the flying.\n\nWhen the survey is complete, present the data to my colleague Horton Gimbleheart in Northwatch.", completion = "What, what!? Can't you see we're under attack here!\n\n<Gimbleheart snatches the readouts from the survey craft, then stuffs them haphazardly into a duffel bag.>\n\nYes sure of course I'll give Nibb's findings careful study. Later. From the safety of the Eastern Kingdoms, if I have any say about it!", objectives = "Speak with Nibb Spindlegear at Honor's Stand to survey the cataclysm's destruction.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25192] = { id = 25192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raggaran's Fury", description = "I will not rest until they're defeated!  Slay them all!\n\n<Raggaran catches his breath.>\n\nTheir stinking lairs are to the north, or to the southwest!", progress = "Quilboar!  Kill them!", completion = "<Again, Raggaran appears calmer.>\n\nYou've done well, stranger.\n\nI'm sorry you had to see me like that.  Thank you for killing the quilboar, but maybe you should leave before I fly into another one of my rages.", objectives = "Kill 5 Razormane Dustrunners and 5 Razormane Battleguards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25193] = { id = 25193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost But Not Forgotten", description = "Today marks the anniversary of my son Kron's passing.  As long as I refused to admit it, I recognize now: Kron is not returning from his crocolisk hunt.\n\nI've been working on a project... something that will memorialize Kron's passion for the hunt.  It's a crocolisk-tooth necklace... rows and rows of teeth, suitable to be worn by only the bravest young orc.  I will place it on his grave.\n\nKron was brave, but he was not strong, like you.  Will you bring me the teeth for my necklace?", progress = "Kron will be remembered.", completion = "Thank you, {race}.  I will get to work on the necklace right away.\n\nBefore Kron died, I had made this for him to wear.  I have no use for it now, but perhaps you might.", objectives = "Obtain 250 Crocolisk Teeth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25194] = { id = 25194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbidden Visitors", description = "Don' worry, Zen'Taji's not in any trouble.  He just been studyin' what happens when the river overflows.\n\nYa see the big tall birds that stand on the riverbank?  Zen'Taji thinks they're in trouble.  The earthquake and the flood pushed the plainstriders over to this side of the water, but they can't fly back, and they're too scared to swim.\n\nThey'll die if they stay here.  Zen'Taji doesn't like violence, but maybe YOU can attack them and scare them over to the other side.  Yes?", progress = "Just beat on 'em, mon.  Trust Zen'Taji, they will run.  It is no big thing.", completion = "I love all the little animals, mon.  I love the big ones, too.  I just hate to see you hurt them like that... but it's for the best.", objectives = "Attack 3 Wayward Plainstriders until they flee toward the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25195] = { id = 25195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's the End of That Raptor", description = "Many creatures died when the water came rushin' into the valley.  The raptors, however, thrived.  They're clever predators, and they've been living off the misfortune of the other creatures.\n\nOne of the raptors is particularly cruel.  He's killing the little animals and letting them rot in the water without even eating them!  He goes by the name of Screamslash, and if we're not careful, he could seriously disrupt the balance of nature.\n\nTravel north, slay him, and give his body back to nature.", progress = "The raptor has always been a quick adapter.", completion = "Something happened to Screamslash when the cataclysm hit, Zen'Taji thinks.  He wasn't always so violent and irrational.\n\nThank you for your help, {name}.  Zen'Taji gonna get back to his studying now.", objectives = "Slay the raptor called Screamslash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25196] = { id = 25196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dranosh'ar Blockade", description = "You should head north from here, {name}.  Speak with Gor the Enforcer at the Dranosh'ar Blockade.  He's been placed in charge of securing shipping lanes for Orgrimmar, and Skull Rock sits right next to his precious dock.  I'm certain he'll be interested in picking up where we left off.", completion = "You're the one who handled the Burning Blade to the south?  I've got ears in all kinds of places, boy, and word travels fast.", objectives = "Report to Gor the Enforcer at the Dranosh'ar Blockade in Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25197] = { id = 25197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Admiral Won't Back Down", description = "What? You want to stay here to fight? Typical {class}, wanting to stay and fight off the Horde while there's still a chance to run for it.\n\nLook, if you really want to save Northwatch, you should report to Admiral Aubrey in the tower behind me. He's keeping his ships here to fight, instead of ferrying us all away like I begged him to.\n\nNow if you'll excuse me, I've got to finish packing!", completion = "You've ventured all the way here from Honor's Stand? Excellent, we could use your experience here.\n\nThey may have breached the walls, but Northwatch isn't going down without a fight.", objectives = "Report to Admiral Aubrey at Northwatch Hold in Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25198] = { id = 25198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winnoa Pineforest", description = "While we've accomplished much here, it would be a tragedy if part of this corruption has escaped our notice.  The corridors of the Wailing Cavern stretch throughout the entire Barrens, and if another spot of wild energy has made its way to the surface...\n\nYou've done enough for me, though. I would simply ask that you let a fellow druid of mine know of what's happened here. You will find Winnoa Pineforest at the Fields of Blood, southwest of here.", sourceObjective = "Speak to Winnoa Pineforest at Vendetta Point in Southern Barrens.While we've accomplished much here, it would be a tragedy if part of this corruption has escaped our notice. The corridors of the Wailing Cavern stretch throughout the entire Barrens, and if another spot of wild energy has made its way to the surface...\n\nYou've done enough for me, though. I would simply ask that you let a fellow druid of mine know of what's happened here. You will find Winnoa Pineforest at the Fields of Blood, southwest of here.", sourceObjectiveStatus = "unverified-source-field" }
quests[25199] = { id = 25199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basic Orders", description = "Hey! You look like you could give us a hand!\n\nIf you're willing to help our cause, we have to get you through training.  Gnome training is brutal and rigorous, so I hope you're ready.\n\nHead over to Drill Sergeant Steamcrank and he'll walk you through what you need to know.  Make sure you follow his orders when he gives them, or else you'll never make it\n\nI'm warning you though, it's tough over there.  Come back to see me, if you make it.", objectives = "Follow Drill Sergeant Steamcrank's cues and then report back to Captain Tread Sparknozzle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25200] = { id = 25200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shredder Shutdown", description = "That no-good Trade Prince Gallywix somehow managed to stow the whole Steamwheedle Sharks footbomb team away on the yacht. I didn't even see any of them!\n\nNow he has them doing his dirty work here at the lumber yard. {name}, you're the <guy/gal> who won the championship for us back home on Kezan. You've got to get rid of them!", progress = "Looks like you might need to tackle one or two more of those Sharks.", completion = "I can't say that I was ever much of a footbomb fan, but you're giving me an appreciation for the game!", objectives = "Slay 8 Steamwheedle Sharks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25201] = { id = 25201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ultimate Footbomb Uniform", description = "Look, kid, I'm here to see to it that you've got a fighting chance at the end game. Thrall's going to need your help in the fight against the Trade Prince.\n\nGreely, Hobart, and I have a plan to put together the ultimate footbomb uniform for you so that you can win the game, but I'm going to need some things first.\n\nLucky for us, this lumber yard is sick with spare shredder parts. Now get out there and give me 110%!", progress = "Let's see what you have there, {name}.", completion = "Yeah, these will do nicely. You did good, kid. I'll see to it that you get the best footbomb uniform ever made.\n\nIn the meantime, you've got other bombs to drop on the Trade Prince's lackeys.", objectives = "Collect 8 Shredder Spare Parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25202] = { id = 25202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fastest Way to His Heart", description = "Oh, <man/girl>! You're never going to guess who's out on the oil platform to the north.\n\n<Izzy shakes her head sadly at you.>\n\nChip's out there, and he's working for the Trade Prince. That cold-hearted snake dropped you like a bad habit and now he's working for the other team. I even heard he's got something goin' on with Candy Cane!\n\nI don't know about you, but if he was my former definitely-real boyfriend, I'd rip his still-beating heart out of his chest.", progress = "What did you decide? Death or forgiveness?", completion = "He got just what he deserved. There, there, don't cry. You'll find someone else that'll treat you right.\n\nHere, let me take that... we wouldn't want people to think that you're crazy.", objectives = "Rip the Still-Beating Heart from out of Chip Endale's chest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25203] = { id = 25203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Kind of Name is Chip, Anyway?", description = "<Dude/Girl>! You're never going to guess who's out on the oil platform to the north.\n\n<Ace shakes head in disbelief.>\n\nChip's out there, and he's working for the Trade Prince. That traitor's now working for the other team. But worse, I heard he's got something goin' on with Candy Cane!\n\nI don't know about you, but if he was shmoozin' up to my former definitely-real girlfriend, I'd do something about it.", completion = "There's no two ways about it... he got exactly what he deserved.", objectives = "Slay Chip Endale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25204] = { id = 25204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Release the Valves", description = "We have to stop Trade Prince Gallywix's oil supply and bring his machines to a grinding halt.\n\nWe're going to need you to go out to the KTC Oil Platform and release the valves to overload the coolant system. After you do that, head to the platform control panel on the platform and set it to blow.", progress = "You have not yet released all four of the valves. The coolant to the platform is still functioning within normal operating parameters.", completion = "All of the lights and indicators on the control panel are going crazy!", objectives = "Release Valves #1 - 4.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25205] = { id = 25205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wolf and The Kodo", description = "My \"associate\" here has some plans for you that I don't agree with.  His actions are hasty, uncontrolled, and irresponsible, and you may end up paying for them with your life.\n\nBefore you work with Gor, first listen to the tale that I have to tell.  It's a moralistic story - a fable - but I believe its lesson will prove valuable.  Speak to me when you are ready.", progress = "Pay close attention to the meaning behind my words, child.", completion = "The moral of the story: hasty, lazy actions have ruinous results.  We mustn't take shortcuts... we must work for our rewards.  I've been trying to tell this story to the \"Enforcer\", but I fear his Hellscream-worshipping skull is a little bit too thick.", objectives = "Hear the moral of Shin Stonepillar's story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25206] = { id = 25206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ignoring the Warnings", description = "Ignore the shaman, soldier.  Certain powers-that-be within the Horde demand that I keep him with me, but I assure you, that Thrall-loving farseer truly sees no farther than the borders of this hut.\n\nElementals war against one another to the west of here.  I normally wouldn't mind, but I need that land clear to secure a broader shipping route to and from the Barrens.  The elementals are normally quite strong, but they are weakened by their attacks against one another.  Use this knowledge to destroy them.", progress = "Elementals?  Pfuh!  No match for the power of the Horde.", completion = "See?  The shaman's tales are nothing but that... a youngling's bedtime stories.  The new Horde takes what it wants, and doesn't waste time with such frivolity.\n\nIf you get a chance, I recommend you tell Shin... and those like him... not to waste any more of your time.", objectives = "Destroy 12 Warring Elementals. You may slay either Furious Earthguards or Teeming Waterguards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25207] = { id = 25207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good-bye, Sweet Oil", description = "There is single big, red button on the platform control console. Clearly if ever there were a button to cause massive explosions, that is it!", completion = "I felt the heat from the explosions all the way over here!", objectives = "Press the Big Red Button to destroy the KTC Oil Platform.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25208] = { id = 25208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tell Silvia", description = "It seems we've found an infestation far worse than the one we expected. Cho'gall is no doubt trying to use the Gordok to gain access to the remnants of Eldre'thalas within Dire Maul, full of the forbidden powers that brought the downfall of the Shen'dralar...\n\nI am rambling. Leave me, {name}. Tell Silvia of what you've learned. Whatever is occuring in Dire Maul must be stopped.", completion = "You're back. What did Estulan say?", objectives = "Talk to Silvia at the Tower of Estulan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25209] = { id = 25209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordunni Threat", description = "Within the High Wilderness to the south lay countless ancient ruins. It's there that the ancestors of the night elves fooled about with arcane magic, and it's there that the Gordunni ogres wander, searching for leftover scraps.\n\nYou'll notice the forest is completely destroyed in that area; the ogres leave only useless muck in their wake, depriving the Horde of valuable resources.\n\nGo and slay the Gordunni there, {name}. Secure the area for the Horde, and only for the Horde!", completion = "You have proven yourself to be a trustworthy and dependable ally, {name}.", objectives = "Kill 16 Gordunni Ogres in the High Wilderness.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25210] = { id = 25210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of Change", description = "A severe illness has fallen over the creatures of this forest. While at first I hoped it was part of nature's course, it has refused to pass.\n\nThe forest stags, normally strong and serene, have suffered the worst. Some waste away in weakness; others froth and rage dangerously. If I am to consult the spirits to learn more of this sickness, I will need the stags' antlers.", progress = "This is a sad task, {name}, but necessary.", completion = "I thank you, {name}. I will study the horns, but the situation has become even more dire since you left.", objectives = "Collect 8 Infected Stag Antlers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25211] = { id = 25211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning Hovel", description = "Don't listen to Rharen. He's as addled as they come. It's his fault that the ale got captured!\n\nAnd what's more, I figure there's a bigger issue here than the ale being stolen. The fact that there's a bunch of orcs runnin' about Dun Algaz after all these years is ridiculous!\n\nTell you what, {class}. You head in there and be sure to drive as many orcs out of those ruins as you can. Dun Algaz isn't good for much anymore, but I'll be damned if we let them just sit in there.", progress = "C'mon now, put some effort into it! I can still smell 'em from here!", completion = "That'll show 'em!  Nice work!", objectives = "Kill 5 Dragonmaw Orcs in Dun Algaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25212] = { id = 25212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vent Horizon", description = "We thought that we could wait for the radiation to subside around Gnomeregan, but it doesn't appear to be getting better.\n\nIf we want to take back our city, we need to make sure it's safe for our troops to enter.\n\nTake these Radiageigatrons, hop in 'Thunderflash' here,  and toss them at the ventilation shafts outside of Gnomeregan. They'll report the radiation levels directly to me.", objectives = "Use Pilot Muzzlesprock's flying machine to toss Radiageigatrons at the vents surrounding Gnomeregan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
